-- ZPause's settings, from the lobby and from a match: the BOIII and T7x
-- builds.
--
-- Generated by tools/mk_t7_uiscripts.py from the Workshop build's
-- ui/zpause/zpausesettings.lua, with only its requires changed -- a ui_script
-- asks for a sibling by bare name. Never edit by hand: an edit here would be
-- undone by the next build, and the two menus would drift apart.
--
-- Dropped in as <client>/ui_scripts/zpause/__init__.lua, which the client
-- runs inside the game's own LUI. The lobby button and the save file are
-- still the frontend's, on the same test the clients' own ui_scripts open on.
--
-- The one thing that is not the same here: the page's background. An image
-- can only arrive in a fastfile and there is none on this route, so the page
-- draws a half-transparent black panel instead. It decides that when it runs
-- -- this is the same file, not a second page.
--
-- A setting saved here goes into the class names of the offline zombies
-- loadouts, as it does on the Workshop build -- but with no mod loaded that
-- is the player's own file rather than a mod's copy. Zombies has no
-- create-a-class, so nothing in a zombies game reads them.
--
-- It also asks for zp_pause_menu's hook, above the frontend guard, because
-- that one runs in a match. The client loads a ui_script in a match too.

require( "zpausepausemenu" )
require( "zpausesettingsdata" )

local Z = CoD.ZPauseSettings
-- ZBUNDLE_PRESENTATION_V1
-- The shared bundle's presentation contract, carried natively: every word this
-- renderer draws already goes through its owner's provider (Z.OwnerWords) and its
-- own catalogs, so a bundle builder finding this marker changes nothing here. It
-- used to add these by rewriting the shipped file, which Xep ruled out on 12
-- October 2026: a fix lives in the owner's own seam, consumed the same way
-- everywhere.
Z.BundlePresentationVersion = 1
Z.saved = {}
Z.dirty = false
-- Whether the save file has actually been read. Nothing is written over a
-- file nobody has read: in a match the loadouts buffer can be out of reach,
-- and a write from there would put an empty set over everything saved.
Z.loaded = false
Z.ByKey = {}
Z.AllRows = {}
for _, page in ipairs( Z.Pages ) do
	for _, row in ipairs( page.rows ) do
		Z.ByKey[row.key] = row
		table.insert( Z.AllRows, row )
	end
end
-- Saved like the rest and on no page: zp_enabled, which the shared menu
-- shows on the bundle's MODS page rather than as a setting of ZPause's own.
-- Black Ops III keeps no dvar once it closes, so a mod switched off has to
-- be written down or it is back the next time the game starts.
for _, row in ipairs( Z.Hidden or {} ) do
	Z.ByKey[row.key] = row
	table.insert( Z.AllRows, row )
end

-- ------------------------------------------------------------------------
-- Words
-- ------------------------------------------------------------------------

-- What the page calls things. The Workshop build links ZPause's own strings
-- in all twelve languages the game ships and a zombies match has them loaded;
-- the frontend and the loose-script clients do not, and Engine.Localize hands
-- back the key it was given when there is no such string -- so the English
-- the table was written from is the fallback, and nobody ever reads a key.
--
-- A key is looked up in the catalog the generator embedded in the data file,
-- and falls back to the English the call site already holds.
--
-- It used to return the English unconditionally, and the reason it had to is
-- the reason this route exists. A `.str` key only resolves where the fastfile
-- carrying it is loaded: ZPause's strings ride in zm_mod, which is a match's
-- zone, and this menu opens in the frontend -- and on the loose clients there
-- is no fastfile at all. A key that does not resolve is drawn as the key, which
-- is exactly what the menu showed in game: rows of ZPAUSE_MENU_DEFAULT under a
-- ZPAUSE_MENU_TITLE. So every key in this file named something defined nowhere,
-- and English every time was the honest answer.
--
-- The catalog is embedded in the shipped Lua, so it needs no fastfile and works
-- in the frontend and on BOIII and T7x where `.str` provably cannot. This is
-- not a second translation route beside that one: it replaces a route that
-- could not work here. The shared translation core underneath it is vendored,
-- pinned bytes (tools/shared_cores.py).
--
-- The lines players read during a match -- every zp_say, zp_say_all and
-- zp_show -- are keyed as they always were, and those still resolve the old
-- way, because a match has zm_mod loaded.
-- **Z.Text is NOT defined here, and must never be.** `Z` is `CoD.ZPauseSettings`
-- itself, and the generated data file -- which this file's require chain pulls
-- in first -- already puts the real lookup there. A definition in this file
-- would assign straight over it, and a body that then called
-- `CoD.ZPauseSettings.Text` would be calling itself: every lookup recurses
-- until the stack gives out, the pcall swallows it, and the English comes back.
-- Compiles, passes every check, translates nothing, for ever.
--
-- It did exactly that for an hour, because a stub returning its English
-- argument was the right answer here for a year and rewriting it in place
-- looked like the smaller change. ZShare's session found the same shadowing in
-- its own tree and said so.
--
-- The lookup's signature is `( key, fallback )`, which is the shape all 38 call
-- sites below already pass, so they reach the catalog with no change.

-- A word of the game's own, which every route has in every language.
Z.Stock = function ( key, english )
	local ok, text = pcall( Engine.Localize, key )
	if not ok or type( text ) ~= "string" or text == "" or text == key then
		return english
	end
	local upper, out = pcall( Engine.ToUpper, text )
	if upper and type( out ) == "string" and out ~= "" then
		return out
	end
	return text
end

-- A line the generator gave a key as well as its English. A row somebody else
-- registered has only the English, and gets it back unchanged -- and so does a
-- line whose English is no longer the key's, which is what a copy re-worded
-- from a row of ours looks like (Z.Words).
Z.Keyed = function ( key, english, fallback )
	if type( english ) ~= "string" or english == "" then
		english = fallback or ""
	end
	if type( key ) ~= "string" or key == "" then
		return english
	end
	return Z.Words( key, english )
end

-- The shared shell's own words: what the registry draws for every mod on the
-- screen -- MODS, CHANGED, ON and OFF on a mod's switch, the host-lock
-- sentences. They are translated here, where this renderer draws them, and
-- never inside B.*: one copy of B runs for the whole screen, and it has to
-- read the same whichever mod happened to load first. The vocabulary is a
-- closed table the generator writes (mk_locale.SHELL); anything not in it is
-- drawn as it came.
Z.Shell = function ( english )
	if type( english ) ~= "string" or english == "" then
		return english or ""
	end
	local keys = Z.ShellKeys
	if type( keys ) ~= "table" or keys[english] == nil then
		return english
	end
	return Z.Words( keys[english], english )
end

-- A mod's own words through that mod's provider in the shared registry -- the
-- kit's presentation ABI, B.Localizers.<owner>. In a bundle this renderer
-- draws every mod's rows, and only the owner can translate its own: ZPause's
-- catalog asked about a ZShare row answers English, and ZShare's about ours
-- would too. A CHANGED copy names the mod it came from in sourceOwner, so it
-- reaches that mod rather than the shell. Whatever no provider translates is
-- offered to the shell vocabulary, and then drawn as it came.
Z.OwnerWords = function ( english, row, tab, controller )
	if type( english ) ~= "string" or english == "" then
		return english or ""
	end
	local owner = nil
	if type( row ) == "table" then
		owner = row.sourceOwner or row.localizationOwner
	end
	if owner == nil and type( tab ) == "table" then
		owner = tab.owner
	end
	owner = owner or Z.Owner
	local providers = CoD.ZBundleSettings ~= nil and CoD.ZBundleSettings.Localizers or nil
	local provider = type( providers ) == "table" and providers[owner] or nil
	if type( provider ) == "table" and provider.version == 1 and type( provider.text ) == "function" then
		local ok, said = pcall( provider.text, english,
			{ owner = owner, row = row, tab = tab, controller = controller } )
		if ok and type( said ) == "string" and said ~= "" and said ~= english then
			return said
		end
	end
	return Z.Shell( english )
end

-- A row's name, and the name of one of its choices, as drawn.
Z.RowLabel = function ( row, tab, controller )
	return Z.OwnerWords( tostring( row.label or row.dvar or "" ), row, tab, controller )
end

-- An action row's name in the game's own pause menu, by the mod that
-- registered it. In a bundle this file draws every mod's actions, and
-- B.ActionLabel is the registry's: one copy for the whole screen, which hands
-- back whatever the mod registered and translates nothing.
Z.ActionWords = function ( action, controller )
	local english = CoD.ZBundleSettings.ActionLabel( action, controller )
	if type( action ) ~= "table" then
		return english
	end
	return Z.OwnerWords( english, action, { owner = action.owner }, controller )
end

Z.ChoiceLabel = function ( row, index, tab, controller )
	local english = ( row.labels or {} )[index]
	if english == nil then
		return nil
	end
	return Z.OwnerWords( tostring( english ), row, tab, controller )
end

-- Whether a value text carries one of the states drawn in front of it, in
-- English or in the language on screen: the control falls back to reading
-- its own text where a recycled option carries no lock model.
Z.StatePrefixed = function ( text )
	for _, key in ipairs( { "ui.locked_value", "ui.disabled_value" } ) do
		for _, pattern in ipairs( { Z.Source( key ), Z.Text( key, "" ) } ) do
			if type( pattern ) == "string" and pattern ~= "" then
				local head = string.match( pattern, "^(.-){value}" )
				if head ~= nil and head ~= "" and string.sub( text, 1, string.len( head ) ) == head then
					return true
				end
			end
		end
	end
	for _, english in ipairs( { "HOST VALUE UNAVAILABLE", "HOST STATUS UNKNOWN" } ) do
		for _, shown in ipairs( { english, Z.Shell( english ) } ) do
			if text == shown then
				return true
			end
		end
	end
	return false
end

-- ------------------------------------------------------------------------
-- Settings
-- ------------------------------------------------------------------------

-- Whether the value a dvar holds is the one a choice stands for, numbers
-- compared as numbers: "0.30" is 0.3.
Z.Same = function ( a, b )
	local na = tonumber( a )
	local nb = tonumber( b )
	if na ~= nil and nb ~= nil then
		return na == nb
	end
	return a == b
end

-- Whether a setting is still at its default. Empty is the obvious case, but
-- the script writes every default into its dvar as a match loads, so after
-- one has been played every setting nobody touched holds its default.
Z.IsDefault = function ( current, row )
	return current == "" or Z.Same( current, row.default )
end

Z.Get = function ( dvar )
	local ok, value = pcall( Engine.DvarString, nil, dvar )
	if ok and type( value ) == "string" then
		return value
	end
	return ""
end

-- Engine.SetDvar is what the game's own settings pages use. Where that did
-- not take, the console's set does it: set is how a dvar that nothing has
-- made yet comes to exist.
Z.Set = function ( controller, dvar, value )
	pcall( Engine.SetDvar, dvar, value )
	if Z.Get( dvar ) ~= value then
		-- A quote inside the value would close the one this opens and
		-- leave the console a malformed command. Nothing the pages offer
		-- has one; a value typed into the console might.
		Engine.Exec( controller, "set " .. dvar .. " \"" .. string.gsub( value, "\"", "" ) .. "\"" )
	end
end

-- The label a row's own default is drawn under, so the page can say what
-- DEFAULT currently means.
Z.DefaultLabel = function ( row, tab, controller )
	for index, value in ipairs( row.values or {} ) do
		if Z.Same( value, row.default ) then
			return Z.ChoiceLabel( row, index, tab, controller ) or value
		end
	end
	return row.default or ""
end

-- What the details panel says a change waits for, and who it is for. Both
-- come from the row -- tools/mk_t7_lobby.py has the table -- because the
-- script is what decides them and a guess made here from a setting's name
-- would be wrong the first time one moved.
Z.Boundary = function ( row, tab, controller )
	return Z.OwnerWords( row.boundary or "", row, tab, controller )
end

-- What a row is waiting for, or -- when it is not waiting for anything
-- because it cannot be changed -- which state is holding it. A boundary on
-- a row nobody can edit says when a change would land that cannot be made.
Z.StatusText = function ( row, tab, controller )
	local who = controller or Z.Who()
	if CoD.ZBundleSettings.RowHostLocked ~= nil and CoD.ZBundleSettings.RowHostLocked( row, tab, who ) then
		return Z.Text( "ui.host_controlled", "HOST CONTROLLED" )
	end
	if CoD.ZBundleSettings.RowForced( row, tab, who ) then
		return Z.Text( "ui.status_overridden", "STATUS: OVERRIDDEN" )
	end
	if row.enabled ~= nil and not CoD.ZBundleSettings.RowEnabled( row, tab, who ) then
		return Z.Text( "ui.status_disabled", "STATUS: DISABLED" )
	end
	return Z.Boundary( row, tab, who )
end

Z.Scope = function ( row, tab, controller )
	if type( row.scope ) ~= "string" or row.scope == "" then
		return Z.Text( "ui.scope_host", "HOST / SHARED" )
	end
	return Z.OwnerWords( row.scope, row, tab, controller )
end

-- A report row -- somebody else's compatibility tab, say -- says what it is
-- and cannot be changed, so the bulk actions step over it. The registry owns
-- the answer, and it is reached through CoD rather than the local below:
-- this is read before that local exists.
Z.Writable = function ( row, tab, controller )
	return CoD.ZBundleSettings.RowWritable( row, tab, controller )
end

-- A setting another setting switches off. The generated page carries the
-- dependency as data -- the dvars it needs, each with the value that counts
-- as off and the default to read an empty one as -- and this is what turns
-- that into the row-level predicate the shared shell asks for.
--
-- An empty dvar is not off. Black Ops III keeps no dvar once it closes, so
-- a page opened before the mod's own save record has been put back reads
-- nothing, and taking that for off would grey half the screen against
-- settings that are on by default.
-- The row builder is handed a row and its category, not a controller, and
-- every caller of it is this player's own screen.
Z.Who = function ()
	local ok, who = pcall( Engine.GetPrimaryController )
	if ok then
		return who
	end
	return nil
end

Z.NeedsMet = function ( controller, row )
	local needs = row.needs
	if needs == nil or #needs == 0 then
		return true
	end

	local all = ( row.needsMode == "all" )
	local everyOne = true

	for _, need in ipairs( needs ) do
		local live = Z.Get( need[1] )
		if live == nil or live == "" then
			live = need[3]
		end
		local off = ( tostring( live ) == tostring( need[2] ) )
		if off and not all then
			return false
		end
		if not off then
			everyOne = false
		end
	end

	if all then
		return not everyOne
	end
	return true
end

-- The reason in place of the description, so a greyed row says what to
-- change rather than only refusing to change.
Z.RowHint = function ( controller, row, tab )
	if row == nil then
		return ""
	end
	local reason = CoD.ZBundleSettings.RowReason( row, tab, controller )
	if reason ~= nil then
		-- A row's own reason is its owner's words; a host lock is the shell's.
		return Z.OwnerWords( reason, row, tab, controller )
	end
	-- No "Default: X." to compose here: this port's page has a field of its own
	-- for the default, and reading it twice is worse than not at all.
	return Z.OwnerWords( row.hint or "", row, tab, controller )
end

-- ------------------------------------------------------------------------
-- Saving
--
-- A mod keeps save files of its own -- players/mods/<folder>/ for a local
-- mod, players/311210/<item>/ for a Workshop item -- and a choice made here
-- goes into this mod's copy of the offline zombies loadouts, in the class
-- names: zombies has no create-a-class, so nothing in a zombies game reads
-- them. What is written is "ZP1" and then five characters for each setting
-- that is not at its default: three naming the setting and two naming its
-- value. The build makes both from the names themselves, so a setting or a
-- choice added in a later version leaves the ones already saved alone.
--
-- These are ZPause's fields and ZPause's alone. ZTweaks keeps its own record
-- in the same save file, in the loadouts' numeric attachment slots, so the
-- two can sit side by side without either erasing the other -- which is only
-- true while neither writes outside what it owns.
-- ------------------------------------------------------------------------

Z.STORAGE = Enum.StorageFileType.STORAGE_ZM_LOADOUTS_OFFLINE
Z.FORMAT = "ZP1"
Z.ENTRY = 5

-- What the record was last found to be, and what the last write did. Four
-- read states have to be told apart and only one of them permits a write:
-- "empty" is a file nobody has written, "valid" is ours, "unknown" is a
-- later ZPause's or somebody else's, and nothing at all is a read that has
-- not happened yet. Reading the last two as empty is how a record this
-- build cannot parse gets quietly replaced by one it can.
Z.state = nil
Z.status = nil
Z.omitted = nil

Z.Fields = function ( controller )
	local fields = {}
	pcall( function ()
		local names = Engine.StorageGetBuffer( controller, Z.STORAGE ).cacLoadouts.customClassName
		for index = 0, 31 do
			local field = names[index]
			if field == nil then
				return
			end
			table.insert( fields, field )
		end
	end )
	return fields
end

-- How many characters a class name holds, found by asking it: a name longer
-- than that comes back shorter, or is refused.
Z.Room = function ( field )
	local keep = field:get() or ""
	local room = 0
	for _, size in ipairs( {
		64,
		32,
		24,
		16,
		12,
		8
	} ) do
		if pcall( field.set, field, string.rep( "0", size ) ) then
			local got = field:get()
			if type( got ) == "string" and string.len( got ) > 0 then
				room = math.min( size, string.len( got ) )
				break
			end
		end
	end
	pcall( field.set, field, keep )
	return room
end

-- dvar -> value for every setting saved away from its default, and whether
-- the file could be read at all. Nothing saved and nothing to read from look
-- the same otherwise, and telling them apart is what keeps a page opened in a
-- match from writing an empty file over the one the lobby saved.
Z.Read = function ( controller )
	local fields = Z.Fields( controller )
	if #fields == 0 then
		Z.state = nil
		return {}, false
	end
	local text = ""
	for _, field in ipairs( fields ) do
		local part = field:get()
		if type( part ) ~= "string" or part == "" then
			break
		end
		text = text .. part
	end
	local saved = {}
	if text == "" then
		Z.state = "empty"
		return saved, true
	end
	if string.sub( text, 1, string.len( Z.FORMAT ) ) ~= Z.FORMAT then
		-- Readable, and not ours to touch. Left exactly as it is: a write
		-- over it would be this build deciding that a record it does not
		-- recognise is a record nobody wanted.
		Z.state = "unknown"
		return saved, true
	end
	Z.state = "valid"
	for at = string.len( Z.FORMAT ) + 1, string.len( text ) - Z.ENTRY + 1, Z.ENTRY do
		local row = Z.ByKey[string.sub( text, at, at + 2 )]
		if row ~= nil then
			local valueKey = string.sub( text, at + 3, at + 4 )
			for index, key in ipairs( row.keys ) do
				if key == valueKey then
					saved[row.dvar] = row.values[index]
				end
			end
		end
	end
	return saved, true
end

Z.Write = function ( controller )
	if not Z.loaded then
		return false
	end
	-- A record this build cannot read is not a record it may replace.
	if Z.state == "unknown" then
		Z.status = "unknown_format"
		return false
	end

	local fields = Z.Fields( controller )
	if #fields == 0 then
		Z.status = "read_pending"
		return false
	end
	local room = Z.Room( fields[1] )
	if room == 0 then
		Z.status = "read_pending"
		return false
	end

	local text = Z.FORMAT
	local omitted = nil
	for _, row in ipairs( Z.AllRows ) do
		local value = Z.saved[row.dvar]
		if value ~= nil then
			for index, known in ipairs( row.values ) do
				if known == value then
					if string.len( text ) + Z.ENTRY <= room * #fields then
						text = text .. row.key .. row.keys[index]
					else
						omitted = omitted or row.dvar
					end
				end
			end
		end
	end

	-- Partial success is not success. A setting that did not fit is one the
	-- player changed and would never get back, so nothing is written, the
	-- change stays dirty to be tried again, and the row that did not fit is
	-- named rather than lost silently. This used to append what fitted,
	-- write, and report success.
	if omitted ~= nil then
		Z.status = "capacity_exhausted"
		Z.omitted = omitted
		return false
	end

	for index, field in ipairs( fields ) do
		local from = (index - 1) * room + 1
		pcall( field.set, field, string.sub( text, from, from + room - 1 ) )
	end

	-- Read the record back the way Z.Read will, and refuse to commit one
	-- that does not say what was just encoded. An assignment the engine
	-- refuses leaves the old characters in place and reports nothing, so
	-- without this a write can commit a record that is half this version
	-- and half the last. Compared as a prefix because the last field may
	-- come back padded to its own width, which the reader already allows.
	local check = ""
	for _, field in ipairs( fields ) do
		local got, part = pcall( field.get, field )
		if not got or type( part ) ~= "string" or part == "" then
			break
		end
		check = check .. part
	end
	if string.sub( check, 1, string.len( text ) ) ~= text then
		Z.status = "verify_mismatch"
		return false
	end

	-- An explicit false is a refusal, not a slow write, and it has to keep
	-- the change dirty. The return used to be ignored entirely.
	local ok, result = pcall( Engine.StorageWrite, controller, Z.STORAGE )
	if not ok or result == false then
		Z.status = "write_rejected"
		return false
	end

	Z.status = "committed"
	Z.omitted = nil
	return true
end

-- Saved when a page closes, not on every press. The flag comes down only
-- once the write is in: Z.Write returns false when there is no field or no
-- room to write to, and it is called through pcall because it can throw, so
-- clearing first threw the change away on the one pass that needed keeping.
Z.Flush = function ( controller )
	if Z.dirty then
		local ok, written = pcall( Z.Write, controller )
		if ok and written == true then
			Z.dirty = false
		end
	end
end

-- Once a game: what was saved goes back into the dvars the first time the
-- frontend starts with this mod loaded, and not again after a match, so a
-- change the host made from the pause menu lasts until the game closes, the
-- same as one typed into the console.
Z.Startup = function ( controller )
	local saved, ok = Z.Read( controller )

	if ok then
		if Z.dirty then
			-- Something changed before the record could be read. Keep those,
			-- take everything else from the file: writing what is in hand
			-- over the file would be an empty set over everything saved.
			for dvar, value in pairs( saved ) do
				if Z.pending == nil or not Z.pending[dvar] then
					Z.saved[dvar] = value
				end
			end
		else
			Z.saved = saved
		end
		-- The record is reachable, which is the thing a write needs to know.
		-- Until 1.6 this was only set on a read taken before anything had
		-- changed, so a setting changed before the first successful read --
		-- which is every change made in a match, where the storage is often
		-- out of reach -- left the record unwritable for the rest of the
		-- session, and the change lasted only as long as its dvar.
		Z.loaded = true
	end

	-- Only a record that was actually read counts as one that has been put
	-- back. Marking the restore done off a read that failed is a game
	-- running on defaults with a full save file sitting beside it.
	if ok and Z.Get( "zp_lobby_restored" ) ~= "1" then
		for dvar, value in pairs( Z.saved ) do
			Z.Set( controller, dvar, value )
		end
		-- And every row the record does not mention, written back to its own
		-- default. The record holds only what differs, so a row missing from
		-- it means DEFAULT -- and leaving the live dvar alone would bring
		-- back a value a reset had already taken out of the record.
		for _, row in ipairs( Z.AllRows ) do
			if Z.saved[row.dvar] == nil and row.default ~= nil then
				Z.Set( controller, row.dvar, row.default )
			end
		end
		Z.Set( controller, "zp_lobby_restored", "1" )
	end
end

-- Neither half of the save can be relied on to be possible at the moment it
-- is asked for. A match often cannot reach the mod's storage, and the
-- frontend's own timer runs once and stops -- and in a bundle ZPause's page
-- may never be opened at all, because the settings row belongs to whichever
-- Z mod drew it. So this keeps looking: it reads the record until it has it,
-- and writes whatever is outstanding as soon as the storage will take it.
--
-- Without it, a change made from the pause menu is a dvar and nothing more:
-- gone when the game closes, and the game after it runs on the defaults.
Z.Keeper = function ()
	-- The lobby button as well, for a route whose frontend the map check
	-- below does not recognise. Both are guarded against a second pass.
	Z.Hook()

	if not Z.loaded or Z.dirty then
		local controller = Engine.GetPrimaryController()
		if controller == nil or controller < 0 then
			return
		end
		if not Z.loaded then
			pcall( Z.Startup, controller )
		end
		if Z.dirty then
			pcall( Z.Flush, controller )
		end
	end
end

-- The save files are read a moment after the frontend starts, so this looks
-- once a second until they are in -- or, after a minute of the game not
-- saying so, reads them anyway.
Z.Wait = function ( parent, tries )
	parent:addElement( LUI.UITimer.newElementTimer( 1000, true, function ()
		Z.Hook()
		local controller = Engine.GetPrimaryController()
		if controller ~= nil and controller >= 0 then
			local ok, ready = pcall( Engine.StorageIsFileReady, controller, Z.STORAGE )
			if ok and ready == true or tries >= 60 then
				Z.Startup( controller )
				return
			end
		end
		-- Every attempt counts, not only the ones that found a controller.
		-- Counting those alone meant a frontend with no primary controller
		-- never reached the minute, and each pass adds a timer element --
		-- so it added one a second for as long as the game was open.
		if tries >= 60 then
			return
		end
		Z.Wait( parent, tries + 1 )
	end ) )
end

-- ------------------------------------------------------------------------
-- The shared tab registry
--
-- CoD.ZBundleSettings is the one seam between the Z mods' menus: each writes
-- its categories into it and the shell draws whatever is there. Whoever loads
-- first builds it, so this creates it only when it is not already there and
-- never replaces a function somebody else put in -- two copies of the same
-- registry would be two half-filled menus.
--
-- ZPause never reads another component's storage or writes to it. A tab that
-- is not ours is drawn from its own get/set/flush/reset, and one that
-- registered none is drawn read-only rather than saved into ZPause's record.
-- ------------------------------------------------------------------------

CoD.ZBundleSettings = CoD.ZBundleSettings or {}
local B = CoD.ZBundleSettings

-- This copy arrives through core_mod, whose zone links the shared artwork.
-- The generated loose ui_scripts copy changes only this delivery capability.
B.BackgroundImageAvailable = B.BackgroundImageAvailable or false
B.Tabs = B.Tabs or {}
B.TabById = B.TabById or {}
B.Components = B.Components or {}
B.ComponentById = B.ComponentById or {}
B.Actions = B.Actions or {}
B.ActionById = B.ActionById or {}

-- A component is a whole mod rather than one of its categories: what the
-- bundle's MODS page switches on and off, and what the title names as the
-- owner of the category on screen. Registering an id already known updates
-- that descriptor in place, so a mod loaded later -- which on T7x can be
-- this very module, loaded again over a live one -- corrects its own
-- registration without orphaning the table an open menu is holding.
B.RegisterComponent = B.RegisterComponent or function ( component )
	if type( component ) ~= "table" or type( component.id ) ~= "string" or component.id == "" then
		return
	end
	local existing = B.ComponentById[component.id]
	if existing ~= nil then
		for key, value in pairs( component ) do
			existing[key] = value
		end
		return existing
	end
	B.ComponentById[component.id] = component
	table.insert( B.Components, component )
	return component
end

-- The components in the order their categories are shown in: ZTweaks 0,
-- ZPause 100, ZShare 200, ZStats 300.
B.GetComponents = B.GetComponents or function ()
	local result = {}
	for _, component in ipairs( B.Components ) do
		table.insert( result, component )
	end
	table.sort( result, function ( left, right )
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.label or left.id ) < tostring( right.label or right.id )
	end )
	return result
end

-- What each mod on this screen calls its own build. The descriptor's own
-- `version` is the authority; a component registered by an older build that
-- has none is looked up in its public settings namespace instead, and one
-- that cannot be found at all reads as v? rather than being left out -- an
-- incomplete registration should be visible while it is being written.
B.ComponentVersions = B.ComponentVersions or {}

B.ComponentVersion = B.ComponentVersion or function ( component, controller )
	if component == nil then
		return nil
	end
	local value = component.version or component.getVersion
		or B.ComponentVersions[component.id]
	if type( value ) == "function" then
		local ok, result = pcall( value, controller, component )
		value = ok and result or nil
	end
	if value == nil or value == "" then
		local legacy = {
			ztweaks = CoD.ZTweaksSettings,
			zpause = CoD.ZPauseSettings,
			zshare = CoD.ZShareSettings,
			zstats = CoD.ZStatsSettings
		}
		local settings = legacy[string.lower( tostring( component.id or "" ) )]
		if settings ~= nil then
			value = settings.Version or settings.version
		end
	end
	if value == nil or value == "" then
		return nil
	end
	-- A version writes itself with or without the v; the line puts one on.
	return string.gsub( tostring( value ), "^%s*[vV]", "" )
end

-- Every registered mod, switched on or not: what is installed is what the
-- line is for. The bundle's own version is deliberately not in it.
B.ComponentVersionsText = B.ComponentVersionsText or function ( controller )
	local labels = {}
	for _, component in ipairs( B.GetComponents() ) do
		local label = string.upper( tostring( component.label or component.id or "MOD" ) )
		local version = B.ComponentVersion( component, controller ) or "?"
		table.insert( labels, label .. " v" .. version )
	end
	return table.concat( labels, " / " )
end

-- Whether a component is switched on. One that registered no getEnabled is
-- taken as on: a mod that cannot say is running, or it would not be here to
-- be asked.
B.ComponentEnabled = B.ComponentEnabled or function ( component, controller )
	if component == nil or type( component.getEnabled ) ~= "function" then
		return true
	end
	local ok, value = pcall( component.getEnabled, controller, component )
	if not ok then
		return true
	end
	return value ~= false and value ~= 0 and value ~= "0"
end

B.SetComponentEnabled = B.SetComponentEnabled or function ( component, controller, enabled )
	if component == nil or type( component.setEnabled ) ~= "function" then
		return false
	end
	local ok = pcall( component.setEnabled, controller, enabled, component )
	return ok
end

-- A mod switched on or off has to show on the page at once, and a component's
-- own getEnabled cannot always answer that quickly: the value it reads is a
-- dvar another write has yet to reach, or a save file, or a next-match state.
-- What was asked for is therefore what the open menu goes by, while the
-- component keeps sole ownership of storing it and of what happens next match.
--
-- Written as an upgrade over whatever is already here rather than as another
-- `or`: a packaged mod and a loose T7x ui_scripts copy share this registry and
-- either may have loaded first, so the pair that arrived first is wrapped in
-- place. The version guard is what keeps that to once.
B.ComponentEnabledOverrides = B.ComponentEnabledOverrides or {}

if ( tonumber( B.LiveComponentToggleVersion ) or 0 ) < 1 then
	local inheritedEnabled = B.ComponentEnabled
	local inheritedSetEnabled = B.SetComponentEnabled

	B.ComponentEnabled = function ( component, controller )
		if component ~= nil and component.id ~= nil
			and B.ComponentEnabledOverrides[component.id] ~= nil then
			return B.ComponentEnabledOverrides[component.id]
		end
		return inheritedEnabled( component, controller )
	end

	B.SetComponentEnabled = function ( component, controller, enabled )
		local ok, accepted = inheritedSetEnabled( component, controller, enabled )
		if ok == false or accepted == false then
			return false
		end
		if component ~= nil and component.id ~= nil then
			B.ComponentEnabledOverrides[component.id] = enabled == true
		end
		return true
	end

	B.LiveComponentToggleVersion = 1
end

-- One mod's settings, or several mods' on one screen. Everything the page
-- calls itself follows from this.
B.IsBundle = B.IsBundle or function ()
	return #B.GetComponents() > 1
end

-- Whether a row can be written at all: the one authority for it, so the
-- renderer, the bulk actions and the aggregate pages cannot disagree about
-- what is informational. A row that is not writable shows the one value it
-- has and no DEFAULT choice, and nothing is wired to a change callback --
-- offering DEFAULT on a status line is offering to set a status.
--
-- An upgrade over whatever registry arrived first rather than another `or`:
-- a loose script carrying an older copy would otherwise decide this for the
-- whole screen.
-- Two things at once, and they are not the same thing.
--
-- An older copy that arrived first has to be dropped, or a loose script
-- carrying version 2 decides row availability for the whole screen. That is
-- the clear below, and it is what the version gate has always been for.
--
-- But a bundle's loader may also set RowWritableVersion = 3 before ZPause
-- loads, to keep its own copies -- ZTweaks' does. That skips the clear, and
-- if that loader exports some of these and not others the renderer calls nil
-- and takes the page with it. So each one is defined only when it is absent:
-- a gap is filled, anything already there is left exactly as it is, and
-- whichever copy won still decides the behaviour.
if ( tonumber( B.RowWritableVersion ) or 0 ) < 5 then
	B.RowEnabled = nil
	B.RowForced = nil
	B.RowForcedValue = nil
	B.RowReason = nil
	B.RowWritable = nil
	B.RowWritableVersion = 5
end

if B.RowEnabled == nil then
	-- Version 2 adds availability per row on top of read-only. A row may
	-- carry `enabled`, a boolean or a function of ( controller, row, tab ),
	-- and one that is off greys where it stands, shows its current value as
	-- a single inert choice, and is passed over by Reset Tab, Randomize and
	-- Reset All. `disabledReason` stands in for its hint while it is off.
	--
	-- No `enabled` means enabled. A callback that errors disables the row:
	-- a predicate that cannot answer must not leave a setting writable,
	-- since the setting behind it is the one that cannot be relied on.
	B.RowEnabled = function ( row, tab, controller )
		-- Version 5. A host-owned row on a client is not enabled for them
		-- either, which is what RowUnavailable and RowWritable already say.
		-- This one lagged, and another mod's button dispatcher reads it.
		if B.RowHostLocked ~= nil and B.RowHostLocked( row, tab, controller ) then
			return false
		end
		if type( row ) ~= "table" then
			return false
		end
		local e = row.enabled
		if e == nil then
			return true
		end
		if type( e ) == "function" then
			local ok, value = pcall( e, controller, row, tab )
			if not ok then
				return false
			end
			e = value
		end
		return not ( e == false or e == 0 or e == "0" )
	end


	-- Version 3 adds an owner-enforced value lock. `forcedValue` is a value,
	-- or a function of ( controller, row, tab ) returning one; nil releases
	-- it. A boolean becomes "1"/"0" and anything else its string form. While
	-- it holds, the row shows the forced value as its only inert choice and
	-- every edit and bulk action steps over it. A callback that errors locks
	-- the row with nothing to show, which is the fail-closed answer: a
	-- predicate that cannot say what the value is must not let it be set.
	--
	-- ZPause declares no lock of its own. The contract is that an owner only
	-- locks a row it also enforces in its own runtime reader, and nothing in
	-- ZPause overrides another setting's effective value. The shim carries it
	-- regardless, because whichever Z mod loads first is the copy the whole
	-- screen runs on: a version-2 copy loading ahead of a mod that does lock
	-- a row would quietly let that row be edited.
end

-- The owner-enforced lock, which the shell asks about two ways.
--
-- Every Z mod reads one of these and they are not interchangeable: ZPause's
-- own renderer asks B.RowForced and gets ( locked, value ); ZTweaks' and
-- ZStats' CHANGED producers ask B.RowOverride and get ( value, locked ). The
-- returns are the other way round, so neither can be an alias of the other.
--
-- Both have to be here whatever the version says. Their own definitions sit
-- behind a `RowWritableVersion < 3` gate, and ZPause publishes 5 -- so in a
-- bundle where ZPause loads first that gate never opens and whichever helper
-- ZPause did not write is simply missing. That is what took CHANGED out of
-- the published bundle: the producer called a nil RowOverride, Z.TabRows
-- caught the error, and an exception became an empty, greyed category.
--
-- So: one implementation, and whichever name is absent is filled from the
-- one that is present, with the returns swapped.
if B.RowOverride == nil and B.RowForced == nil then
	B.RowOverride = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return nil, false
		end
		local f = row.forcedValue
		if f == nil then
			return nil, false
		end
		if type( f ) == "function" then
			-- A row builder is handed no controller, so the callback gets
			-- this player's own rather than nil. Z.Who is Black Ops III's
			-- primary controller; Black Ops II has no such call and 0 is
			-- the only controller its lobby menu ever runs for.
			local who = controller
			if who == nil then
				who = type( Z.Who ) == "function" and Z.Who() or 0
			end
			local ok, value = pcall( f, who, row, tab )
			if not ok then
				-- Fail closed: a predicate that cannot say what the value
				-- is must not leave the row writable.
				return nil, true
			end
			f = value
		end
		if f == nil then
			return nil, false
		end
		if f == true then
			return "1", true
		end
		if f == false then
			return "0", true
		end
		if type( f ) ~= "string" and type( f ) ~= "number" then
			-- Locked, but with nothing a row can show: tostring on a table
			-- would put its address on screen as the value.
			return nil, true
		end
		return tostring( f ), true
	end
end

if B.RowOverride == nil then
	B.RowOverride = function ( row, tab, controller )
		local locked, value = B.RowForced( row, tab, controller )
		return value, locked
	end
end

if B.RowForced == nil then
	B.RowForced = function ( row, tab, controller )
		local value, locked = B.RowOverride( row, tab, controller )
		return locked, value
	end
end

if B.RowForcedValue == nil then
	B.RowForcedValue = function ( row, tab, controller )
		local _, value = B.RowForced( row, tab, controller )
		return value
	end

	-- The line that stands in for the hint: the lock's reason while a row is
	-- locked, the disabled one while it is switched off, nothing otherwise.
	-- Either may be text or the same callback shape.
end

if B.RowReason == nil then
	B.RowReason = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return nil
		end
		local reason = nil
		if B.RowHostLocked( row, tab, controller ) then
			-- Said here rather than left to each mod: a row is host-owned by
			-- default, so most rows locked this way never declared anything
			-- and would otherwise show their ordinary hint and no
			-- explanation. The unknown case gets its own words, because
			-- "ask the host" is wrong advice while the menu does not yet
			-- know whether you are the host.
			if B.HostStatus( controller ) == "UNKNOWN" then
				return "Locked while this menu does not know whether you are the host. It unlocks by itself if you are."
			end
			return "The host owns this setting. It is theirs to change, and the value here is not read from them."
		end
		if B.RowForced( row, tab, controller ) then
			reason = row.overrideReason
		elseif not B.RowEnabled( row, tab, controller ) then
			reason = row.disabledReason
		end
		if type( reason ) == "function" then
			local ok, value = pcall( reason, controller, row, tab )
			if not ok then
				return nil
			end
			reason = value
		end
		if reason == nil then
			return nil
		end
		return tostring( reason )
	end

end

-- Version 5: who owns a row, and whether we know yet.
--
-- `authority` is machine-readable and separate from the visual `scope`.
-- Exactly "player" opts a row into personal writes; anything else -- missing
-- or malformed included -- stays host-owned. A mod that says nothing is
-- therefore host-owned, which is the safe way round. ZPause's own rows are
-- all host/shared and declare nothing, so none of this changes what ZPause
-- offers a host; what it changes is that a client can no longer write them.
--
-- UNKNOWN is locked. Not knowing whether this player is the host is not a
-- reason to let them write the host's settings, and a lobby query that fails
-- must not hand out host privilege in a context nobody has established.
--
-- None of it is a security boundary. A grey selector stops a menu, not a
-- script, so the owner still enforces authority where the setting is acted
-- on. This is about not showing somebody a control that cannot work.

if B.HostStatus == nil then
	-- Exactly "HOST", "CLIENT" or "UNKNOWN", asked again while the menu is
	-- open rather than frozen when it was built: a host migration or a
	-- lobby-to-match move changes the answer underneath it.
	B.HostStatus = function ( controller )
		-- Black Ops III answers through the active lobby's own model, and
		-- Engine.IsLobbyHost otherwise. Which lobby is the live one has to
		-- be settled first: both models exist at once and the stale one
		-- answers just as readily, so reading them in a fixed order is how a
		-- private-lobby host whose gameClient.isHost still says false reads
		-- as a client, with their own settings locked in front of them.
		-- Every engine name below is read through a pcall, and anything that
		-- cannot be read leaves this at UNKNOWN -- which v5 treats as
		-- locked. The loose-script routes load this same file without a
		-- fastfile behind it, and a settings page that throws is a settings
		-- page that does not open.
		if controller == nil then
			local gotOk, got = pcall( Engine.GetPrimaryController )
			controller = gotOk and got or 0
		end
		local lobbyOk, private, game = pcall( function ()
			return Enum.LobbyType.LOBBY_TYPE_PRIVATE, Enum.LobbyType.LOBBY_TYPE_GAME
		end )
		if not lobbyOk or private == nil or game == nil then
			return "UNKNOWN"
		end
		-- Which lobby is live has to be known, not inferred from an
		-- absence. Being out of a match does not say whether the frontend
		-- lobby is the private one or the game one, so an unavailable
		-- IsLobbyActive with IsInGame false leaves this unknown rather than
		-- guessing private -- a wrong guess there reads the wrong model and
		-- can call a host a client.
		local okActive, active = pcall( Engine.IsLobbyActive, game )
		local okInGame, inGame = pcall( Engine.IsInGame )
		local saidActive = okActive and ( active == true or active == false or active == 0 or active == 1 )
		local saidInGame = okInGame and ( inGame == true or inGame == false or inGame == 0 or inGame == 1 )
		local lobby = nil
		if saidInGame and ( inGame == true or inGame == 1 ) then
			lobby = game
		elseif saidActive then
			lobby = ( active == true or active == 1 ) and game or private
		end
		if lobby == nil then
			return "UNKNOWN"
		end

		-- The lobby's own model root, which is where the game reads this
		-- from. An explicit false has to survive being read, which is why
		-- this is not written as `model and value or nil` -- that turns
		-- false into nil and nil into UNKNOWN, which v5 treats as locked.
		local value = nil
		local ok, got = pcall( function ()
			local root = DataSources.LobbyRoot.getModel( controller )
			local name = lobby == game
				and "gameClient.isHost" or "privateClient.isHost"
			local model = Engine.GetModel( root, name )
			if model ~= nil then
				return Engine.GetModelValue( model )
			end
		end )
		if ok and got ~= nil then
			value = got
		end

		-- Only the answers this means something by. A model can hand back
		-- a string of its own -- "unavailable" and the like -- and taking
		-- anything that is not false for a yes is how a client ends up
		-- holding the host's controls.
		local answer = function ( v )
			if v == true or v == 1 or v == "1" then
				return "HOST"
			end
			if v == false or v == 0 or v == "0" then
				return "CLIENT"
			end
			return nil
		end

		local said = answer( value )
		if said ~= nil then
			return said
		end

		-- A model that is absent, or that answered something this does not
		-- recognise, is not a host: the fallback is the API, asked about the
		-- lobby chosen above rather than whichever one it would pick for
		-- itself. Past that, unknown -- which v5 treats as locked.
		ok, got = pcall( Engine.IsLobbyHost, lobby )
		if ok then
			said = answer( got )
			if said ~= nil then
				return said
			end
		end
		return "UNKNOWN"
	end
end

if B.RowAuthority == nil then
	B.RowAuthority = function ( row, tab )
		-- A report page is this client's reading of their own match, so it
		-- is theirs however the rows under it are annotated.
		if tab ~= nil and tab.role == "report" then
			return "player"
		end
		if type( row ) ~= "table" then
			return "host"
		end
		-- A tab may declare the authority for everything on it, and a row
		-- that says nothing takes it.
		local authority = row.authority
		if authority == nil and tab ~= nil then
			authority = tab.authority
		end
		if authority == "player" then
			return "player"
		end
		return "host"
	end
end

if B.RowHostLocked == nil then
	-- Not writable because it is not theirs, which is a different answer
	-- from switched off and from locked to a value, and reads differently.
	B.RowHostLocked = function ( row, tab, controller )
		if B.RowAuthority( row, tab ) == "player" then
			return false
		end
		return B.HostStatus( controller ) ~= "HOST"
	end
end

if B.RowUnavailable == nil then
	-- Wider than not-writable, and the question the bulk actions ask to
	-- find out whether an owner has anything on screen they are allowed to
	-- touch: off, locked to a value, or not theirs all answer yes.
	B.RowUnavailable = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return true
		end
		if B.RowHostLocked( row, tab, controller ) then
			return true
		end
		if not B.RowEnabled( row, tab, controller ) then
			return true
		end
		if B.RowForced( row, tab, controller ) then
			return true
		end
		return false
	end
end

if B.RowHostValue == nil then
	-- What goes where the value would, on a row this player does not own.
	--
	-- Never their own saved dvar: that is a local value wearing a host-owned
	-- label, which is worse than admitting the host's cannot be read. There
	-- is no verified cross-port transport for a live host value yet -- the
	-- GSC relays both ports have start after a match loads, so they cannot
	-- show one in the pre-match lobby at all -- so this is honest text.
	--
	-- Deliberately not `forcedValue`. That contract also changes the
	-- effective runtime setting, and "we cannot read the host's value" is
	-- not "the owner has overridden it to this". Conflating them would make
	-- a transport gap look like a gameplay override.
	--
	-- nil means the ordinary value is fine to show.
	B.RowHostValue = function ( row, tab, controller )
		if not B.RowHostLocked( row, tab, controller ) then
			return nil
		end
		if B.HostStatus( controller ) == "UNKNOWN" then
			return "HOST STATUS UNKNOWN"
		end
		return "HOST VALUE UNAVAILABLE"
	end
end

if B.RowAvailabilityStamp == nil then
	-- Everything about a row's availability, as one comparable value.
	--
	-- A live watcher visits every row and needs to tell "nothing has
	-- changed" from "rebuild this" without re-deriving the row or rebuilding
	-- the list on every pass. A BO2 native button in particular has to
	-- record its own stamp when it is made, because without that baseline
	-- the watcher reads every pass as a change and rebuilds the active
	-- category continuously.
	B.RowAvailabilityStamp = function ( row, tab, controller )
		return tostring( B.RowEnabled( row, tab, controller ) )
			.. "|" .. tostring( B.RowWritable( row, tab, controller ) )
			.. "|" .. tostring( B.RowHostLocked( row, tab, controller ) )
			.. "|" .. tostring( B.RowForcedValue( row, tab, controller ) )
			.. "|" .. tostring( B.RowReason( row, tab, controller ) )
	end
end

if B.RowWritable == nil then
	B.RowWritable = function ( row, tab, controller )
		if type( row ) ~= "table" then
			return false
		end
		if row.boundary == "READ ONLY" or row.ztReadOnly == true
			or row.readOnly == true or row.writable == false
			or row.editable == false then
			return false
		end
		if tab ~= nil and ( tab.role == "report" or tab.role == "changed" ) then
			return false
		end
		if not B.RowEnabled( row, tab, controller ) then
			return false
		end
		if B.RowForced( row, tab, controller ) then
			return false
		end
		-- Version 5. A host-owned row on a client, or on a player whose
		-- host status is not known yet, is not theirs to write.
		if B.RowHostLocked( row, tab, controller ) then
			return false
		end
		return #( row.values or {} ) > 0
	end
end


-- Two different questions, and keeping them apart is the contract. Visible is
-- whether a category exists on this screen at all -- a platform or a build
-- that cannot carry it. Enabled is whether it can be walked into, which a
-- category loses when the mod that owns it is switched off.
B.TabVisible = B.TabVisible or function ( tab, controller )
	if tab == nil then
		return false
	end
	if type( tab.visible ) ~= "function" then
		return tab.visible ~= false
	end
	local ok, value = pcall( tab.visible, controller, tab )
	return ok and value ~= false
end

B.TabEnabled = B.TabEnabled or function ( tab, controller )
	if tab == nil then
		return false
	end
	-- MODS is how a switched-off mod is switched back on, so it is never
	-- closed by one.
	if tab.role == "mods" then
		return true
	end
	-- Only the host's own switch closes a category. A client's copy of that
	-- setting is their saved preference, not what is running in this match,
	-- and closing their categories on the strength of it takes away the
	-- personal rows they do own -- their character preference, their own HUD
	-- -- on a mod the host has running. Host-owned rows stay locked inside.
	local component = B.ComponentById[tab.owner]
	if component ~= nil and not B.ComponentEnabled( component, controller )
		and ( B.HostStatus == nil or B.HostStatus( controller ) == "HOST" ) then
		return false
	end
	if type( tab.enabled ) ~= "function" then
		return tab.enabled ~= false
	end
	local ok, value = pcall( tab.enabled, controller, tab )
	return ok and value ~= false
end

-- Written as an upgrade over whatever arrived first rather than another `or`:
-- a registry supplied by an older loose script would still be dropping a
-- switched-off mod's categories, and a bundle would then look different
-- depending on which copy loaded first. Categories used to disappear; they
-- stay and go grey, so what a bundle carries is discoverable while switched
-- off and MODS is still the only place that turns it back on.
if ( tonumber( B.DisabledTabVisibilityVersion ) or 0 ) < 1 then
	B.GetTabs = function ( controller )
		local result = {}
		for _, tab in ipairs( B.Tabs ) do
			if B.TabVisible( tab, controller ) then
				table.insert( result, tab )
			end
		end
		if B.IsBundle() and B.ModsTab ~= nil and B.TabVisible( B.ModsTab, controller ) then
			table.insert( result, B.ModsTab )
		end
		table.sort( result, function ( left, right )
			if left.role == "mods" or right.role == "changed" then
				return true
			end
			if right.role == "mods" or left.role == "changed" then
				return false
			end
			local leftOwner = B.ComponentById[left.owner]
			local rightOwner = B.ComponentById[right.owner]
			local leftOwnerOrder = tonumber( leftOwner ~= nil and leftOwner.order ) or 1000
			local rightOwnerOrder = tonumber( rightOwner ~= nil and rightOwner.order ) or 1000
			if leftOwnerOrder ~= rightOwnerOrder then
				return leftOwnerOrder < rightOwnerOrder
			end
			local leftOrder = tonumber( left.order ) or 1000
			local rightOrder = tonumber( right.order ) or 1000
			if leftOrder ~= rightOrder then
				return leftOrder < rightOrder
			end
			return tostring( left.label or left.id ) < tostring( right.label or right.id )
		end )
		return result
	end
	B.DisabledTabVisibilityVersion = 1
end

-- An action is a press rather than a setting -- ZPause's own pause is the
-- first of them -- and belongs to the lists the game's own menus draw. The
-- registry holds them so one merged pause menu can show everybody's without
-- knowing what any of them do.
B.RegisterAction = B.RegisterAction or function ( action )
	if type( action ) ~= "table" or type( action.id ) ~= "string" or action.id == "" then
		return
	end
	local existing = B.ActionById[action.id]
	if existing ~= nil then
		for key in pairs( existing ) do
			existing[key] = nil
		end
		for key, value in pairs( action ) do
			existing[key] = value
		end
		return
	end
	B.ActionById[action.id] = action
	table.insert( B.Actions, action )
end

-- The actions worth drawing right now. visible() is asked every time rather
-- than cached: whether ZPause can take a pause is a thing that changes while
-- the game runs.
B.GetActions = B.GetActions or function ( controller )
	local result = {}
	for _, action in ipairs( B.Actions ) do
		local shown = true
		if type( action.visible ) == "function" then
			local ok, value = pcall( action.visible, controller, action )
			shown = ok and value ~= false
		end
		if shown and B.ComponentEnabled( B.ComponentById[action.owner], controller ) then
			table.insert( result, action )
		end
	end
	table.sort( result, function ( left, right )
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.id ) < tostring( right.id )
	end )
	return result
end

-- The words on an action's row, which for a toggle depend on what the game
-- is doing: PAUSE GAME, or UNPAUSE GAME while it is paused.
B.ActionLabel = B.ActionLabel or function ( action, controller )
	local label = action ~= nil and action.label or nil
	if type( label ) == "function" then
		local ok, value = pcall( label, controller, action )
		label = ok and value or nil
	end
	return tostring( label or ( action ~= nil and action.id ) or "" )
end

B.ActionEnabled = B.ActionEnabled or function ( action, controller )
	if action == nil or type( action.enabled ) ~= "function" then
		return true
	end
	local ok, value = pcall( action.enabled, controller, action )
	if not ok then
		return true
	end
	return value ~= false
end

-- A second registration of the same id replaces that descriptor in place,
-- rather than adding another or swapping the table: a menu already built
-- holds a reference to it, and on T7x a module can be loaded again over a
-- live one.
B.RegisterTab = B.RegisterTab or function ( tab )
	if type( tab ) ~= "table" or type( tab.id ) ~= "string" or tab.id == "" then
		return
	end
	local existing = B.TabById[tab.id]
	if existing ~= nil then
		for key in pairs( existing ) do
			existing[key] = nil
		end
		for key, value in pairs( tab ) do
			existing[key] = value
		end
		return
	end
	B.TabById[tab.id] = tab
	table.insert( B.Tabs, tab )
	-- A mod written against the older registry registers categories and no
	-- component. It still belongs on the MODS page, so one is made from what
	-- the category says about its owner -- without the enable callbacks,
	-- which makes it a row that reports rather than switches.
	if tab.owner ~= nil and tab.owner ~= "zbundle" and B.ComponentById[tab.owner] == nil then
		B.RegisterComponent( {
			id = tab.owner,
			label = tab.ownerLabel or tab.owner,
			order = tab.ownerOrder or tab.order
		} )
	end
end

-- The order the tabs are drawn in, which has to be the same whichever mod
-- happened to load first. MODS is the bundle's own and comes before
-- everything; CHANGED is the bundle's own and comes after everything;
-- between them each component's categories sit together, in the component's
-- order and then their own -- ZTweaks 1-99, ZPause 100, ZShare 200,
-- ZStats 300.
--
-- A component switched off keeps its place on MODS and loses its categories,
-- since there is nothing to edit for a mod that will not be there next
-- match. CHANGED stays: it is the shell's own.
B.GetTabs = B.GetTabs or function ( controller )
	local result = {}
	for _, tab in ipairs( B.Tabs ) do
		if tab.role == "changed" or B.ComponentEnabled( B.ComponentById[tab.owner], controller ) then
			table.insert( result, tab )
		end
	end
	if B.IsBundle() and B.ModsTab ~= nil then
		table.insert( result, B.ModsTab )
	end
	table.sort( result, function ( left, right )
		if left.role == "mods" or right.role == "changed" then
			return true
		end
		if right.role == "mods" or left.role == "changed" then
			return false
		end
		local leftOwner = B.ComponentById[left.owner]
		local rightOwner = B.ComponentById[right.owner]
		local leftOwnerOrder = tonumber( leftOwner ~= nil and leftOwner.order ) or 1000
		local rightOwnerOrder = tonumber( rightOwner ~= nil and rightOwner.order ) or 1000
		if leftOwnerOrder ~= rightOwnerOrder then
			return leftOwnerOrder < rightOwnerOrder
		end
		local leftOrder = tonumber( left.order ) or 1000
		local rightOrder = tonumber( right.order ) or 1000
		if leftOrder ~= rightOrder then
			return leftOrder < rightOrder
		end
		return tostring( left.label or left.id ) < tostring( right.label or right.id )
	end )
	return result
end

Z.Owner = "zpause"

-- Black Ops III hands get() the dvar and the row; a dvar belongs to no
-- controller, so there is none to take. The dvar is the live value, which is
-- the whole point: the script reads the same one.
Z.TabGet = function ( dvar, row )
	return Z.Get( dvar )
end

-- The one place a setting is written. The dvar is the live value and the save
-- record follows it, so a change made here is in the running game at the next
-- pause and still there the next time the game starts.
-- DEFAULT is two things at once and both of them matter. The dvar gets the
-- row's declared default, spelled out, because that is what the screen reads
-- back -- an empty dvar can come back as whatever the engine registered the
-- name with, which is how a row sat in CHANGED while its own selector said
-- DEFAULT. The save record gets nothing, so the setting goes on following
-- whatever default the build carries rather than being pinned to this one's.
--
-- An empty value from an older shell means the same thing and is translated
-- here: a bundle can be a mix of versions, and only this end knows what the
-- row's default is.
Z.TabSet = function ( controller, dvar, value, row )
	if value == "" and row ~= nil and row.default ~= nil then
		value = row.default
	end
	Z.Set( controller, dvar, value )
	-- Which settings this session has an opinion about, kept apart from
	-- their values: a setting put back to DEFAULT is remembered by having
	-- been touched, since its value is its absence. It is what lets a
	-- record read after a change was made be merged with rather than
	-- written over.
	Z.pending = Z.pending or {}
	Z.pending[dvar] = true
	if value == "" or ( row ~= nil and Z.Same( value, row.default ) ) then
		-- DEFAULT saves nothing, so the setting keeps following whatever
		-- default the script carries rather than being pinned to this
		-- build's.
		Z.saved[dvar] = nil
	else
		Z.saved[dvar] = value
	end
	Z.dirty = true
end

Z.TabFlush = function ( controller, tab )
	Z.Flush( controller )
end

-- The owner-wide reset another mod's shell may call instead of walking our
-- rows itself. It writes and flushes ZPause and nothing else, and it does not
-- rebuild anything: the shell that asked owns the one rebuild that follows
-- the whole transaction.
Z.TabReset = function ( controller, menu, tab )
	for _, page in ipairs( Z.Pages ) do
		for _, row in ipairs( page.rows or {} ) do
			Z.TabSet( controller, row.dvar, row.default, row )
		end
	end
	Z.Flush( controller )
end

-- The generated pages carry a dependency as data; the shared shell asks for
-- a predicate on the row. Turned into one here, once, rather than written
-- into the generated file: that file is data both this menu and the pause
-- menu read, and logic in it would be logic in two places.
-- The dvars some other row's availability is reading. Changing one of
-- these has to rebuild the rows; changing anything else does not.
Z.Parents = {}

for _, page in ipairs( Z.Pages ) do
	for _, row in ipairs( page.rows or {} ) do
		if row.needs ~= nil and row.enabled == nil then
			local owned = row
			owned.enabled = function ( controller )
				return Z.NeedsMet( controller, owned )
			end
		end
		for _, need in ipairs( row.needs or {} ) do
			Z.Parents[need[1]] = true
		end
	end
end

for _, page in ipairs( Z.Pages ) do
	B.RegisterTab( {
		id = page.id,
		-- The caption and the hint are resolved again when the page opens:
		-- this runs as the module loads, which in the frontend is before
		-- ZPause's own strings are anywhere to be found.
		label = Z.Text( page.titleKey, page.title ),
		labelKey = page.titleKey,
		labelText = page.title,
		hint = Z.Text( page.hintKey, page.hint ),
		hintKey = page.hintKey,
		hintText = page.hint,
		owner = Z.Owner,
		ownerLabel = "ZPause",
		order = page.order,
		rows = page.rows,
		get = Z.TabGet,
		set = Z.TabSet,
		flush = Z.TabFlush,
		reset = Z.TabReset
	} )
end

-- ------------------------------------------------------------------------
-- ZPause as the bundle knows it
-- ------------------------------------------------------------------------

-- One row, one switch, and the description under it, on the bundle's MODS
-- page. zp_enabled is a real switch and not a cosmetic one -- the script
-- reads it as a match loads and installs nothing at all when it is off --
-- which is why the boundary says NEXT MATCH.
B.RegisterComponent( {
	id = Z.Owner,
	label = "ZPause",
	version = Z.Version,
	order = 100,
	description = Z.Text( "ui.component_hint", "The synced co-op pause: the combos, the chat words, voting, and what a pause freezes." ),
	boundary = "NEXT MATCH",
	getEnabled = function ()
		local value = Z.Get( "zp_enabled" )
		return value == "" or value ~= "0"
	end,
	setEnabled = function ( controller, enabled )
		Z.TabSet( controller, "zp_enabled", enabled and "1" or "0" )
		Z.Flush( controller )
	end
} )

-- The two categories the shell owns rather than any one mod. Neither is
-- registered over one that is already there: whichever Z mod loaded first
-- brought its own, and one of each is the whole point of them.
if B.TabById["zbundle_changed"] == nil then
	B.RegisterTab( {
		id = "zbundle_changed",
		label = "CHANGED",
		hint = "Settings changed from their defaults, across every mod on this screen.",
		owner = "zbundle",
		ownerLabel = "ZBundle",
		order = 1000000,
		role = "changed",
		rows = function ()
			local rows = {}
			for _, tab in ipairs( B.Tabs ) do
				if tab.role ~= "report" and tab.role ~= "changed" and tab.role ~= "mods" then
					for _, row in ipairs( Z.TabRows( tab ) ) do
						local current = Z.RowGet( row, tab )
						-- A button has no value and no default, so there is
						-- nothing for this page to report about it.
						if row.kind == "button" then
							current = nil
						end
						if ( B.RowHostLocked == nil or not B.RowHostLocked( row, tab ) ) and not Z.IsDefault( current, row ) then
							-- A copy: the row here reports, and the one on
							-- its own category is still the one that edits.
							-- Nothing here writes to another mod.
							local copy = {}
							for key, value in pairs( row ) do
								copy[key] = value
							end
							-- Its words are composed here, so they are translated here, each part
							-- by the mod the row belongs to. Every key comes off the copy: a key
							-- left on a row whose words have changed draws the row it was copied
							-- from -- its first choice for the value, its bare name without the
							-- owner in front. sourceOwner says whose it is, so whichever renderer
							-- draws it reaches that mod's provider rather than the shell's.
							local label = string.upper( tostring( current ) )
							for index, value in ipairs( row.values or {} ) do
								if Z.Same( current, value ) then
									label = Z.ChoiceLabel( row, index, tab ) or label
									break
								end
							end
							local owner = tostring( tab.ownerLabel or tab.owner or "MOD" )
							local note = Z.OwnerWords( "Set on {owner}'s own category, which is where it can be changed.", row, tab )
							note = string.gsub( note, "{owner}", function () return owner end )
							copy.label = string.upper( owner ) .. " - " .. Z.RowLabel( row, tab )
							copy.hint = Z.OwnerWords( tostring( row.hint or "" ), row, tab ) .. "  " .. note
							copy.sourceOwner = tab.owner
							copy.labelKey, copy.hintKey, copy.choiceKeys = nil, nil, nil
							-- Never translated: B.RowWritable reads this exact string as the mark
							-- of a row nobody may write. It is translated where it is drawn.
							copy.boundary = "READ ONLY"
							copy.boundaryKey = nil
							copy.default = current
							copy.values = { current }
							copy.labels = { label }
							table.insert( rows, copy )
						end
					end
				end
			end
			return rows
		end
	} )
end

B.ModsTab = B.ModsTab or {
	id = "zbundle_mods",
	label = "MODS",
	hint = "Switch each mod on this screen on or off.",
	owner = "zbundle",
	ownerLabel = "ZBundle",
	order = -1000000,
	role = "mods",
	rows = function ()
		local rows = {}
		for _, component in ipairs( B.GetComponents() ) do
			table.insert( rows, {
				dvar = "zbundle_component_" .. component.id,
				label = string.upper( tostring( component.label or component.id ) ),
				hint = component.description or "Switch this mod on or off.",
				-- A mod that registered no switch is reported and not moved.
				boundary = type( component.setEnabled ) == "function"
					and ( component.boundary or "NEXT MATCH" ) or "READ ONLY",
				scope = "HOST / SHARED",
				kind = "choice",
				default = "1",
				values = { "0", "1" },
				labels = { "OFF", "ON" },
				zpComponent = component
			} )
		end
		return rows
	end,
	get = function ( dvar, row )
		return B.ComponentEnabled( row.zpComponent, Engine.GetPrimaryController() ) and "1" or "0"
	end,
	set = function ( controller, dvar, value, row )
		B.SetComponentEnabled( row.zpComponent, controller, value ~= "0" )
	end
}

-- ------------------------------------------------------------------------
-- What another mod's menu may ask ZPause to do
--
-- CoD.ZPauseAPI is the Lua half of the contract level.zmods carries in the
-- script: a menu that wants to pause the game calls this rather than
-- knowing how a press gets from a menu to a server. What it does know is
-- the road the pause menu already uses -- Engine.SendMenuResponse() under
-- the menu name "zpause", which zpause.gsc waits on -- and the script takes
-- it in at the same door the chat words and the button combo use, so the
-- vote, the cooldown and zp_max_pauses all still have their say.
--
-- Every player's, since 1.7 (Xep, 11 October 2026): the row is the combo on
-- a menu, and a press from anybody goes through the combo's gates in the
-- script - zp_host_only included, which also takes the row off the screen of
-- a player it would turn away.
-- ------------------------------------------------------------------------

CoD.ZPauseAPI = CoD.ZPauseAPI or {}
local A = CoD.ZPauseAPI

A.MENU = "zpause"

-- What the server last told this player, for a game that is not the server.
-- The dvars the script publishes are the host's own -- the host's client is
-- the host's server -- so a client reads nothing there. zpause.gsc tells
-- every player instead (zp_ui_tell), as a script notify named zpause_state
-- carrying four numbers: running, paused for this player, the menu is the
-- pause, and whether zp_host_only leaves them a pause to ask for. Sent when it
-- changes and every two seconds, so a state older than twenty is one nobody
-- is sending any more: the match ended without saying so, or this is another
-- match, and ZPause may not be in it.
A.STATE_EVENT = "zpause_state"
A.STATE_FRESH = 20000

A.Now = function ()
	local ok, now = pcall( Engine.milliseconds )
	if ok and type( now ) == "number" then
		return now
	end
	ok, now = pcall( Engine.CurrentGameTime )
	if ok and type( now ) == "number" then
		return now
	end
	return nil
end

A.TakeState = function ( data )
	if type( data ) ~= "table" then
		return
	end
	Z.ClientState = {
		active = tonumber( data[1] ) == 1,
		paused = tonumber( data[2] ) == 1,
		menuPause = tonumber( data[3] ) == 1,
		allowed = tonumber( data[4] ) == 1,
		at = A.Now()
	}
end

A.State = function ()
	local state = Z.ClientState
	if type( state ) ~= "table" or not state.active then
		return nil
	end
	local now = A.Now()
	if now == nil or state.at == nil or now < state.at or now - state.at > A.STATE_FRESH then
		return nil
	end
	return state
end

-- Once, on the root, for the primary controller: the notify arrives whether or
-- not a menu is open, and the pause menu reads the last one when it builds.
A.WatchState = function ()
	if CoD.ZPauseStateWatching then
		return true
	end
	if LUI.roots == nil or LUI.roots.UIRootFull == nil then
		return false
	end
	local ok, controller = pcall( Engine.GetPrimaryController )
	if not ok or type( controller ) ~= "number" then
		return false
	end
	local watching = pcall( function ()
		LUI.roots.UIRootFull:subscribeToGlobalModel( controller, "PerController", "scriptNotify", function ( model )
			if type( IsParamModelEqualToString ) ~= "function" or not IsParamModelEqualToString( model, A.STATE_EVENT ) then
				return
			end
			if type( CoD.GetScriptNotifyData ) == "function" then
				A.TakeState( CoD.GetScriptNotifyData( model ) )
			end
		end )
	end )
	CoD.ZPauseStateWatching = watching
	return watching
end

A.IsHost = function ()
	local ok, host = pcall( Engine.IsLobbyHost, Enum.LobbyType.LOBBY_TYPE_GAME )
	return ok and host == true
end

-- Whether there is a game to pause. For the host the script publishes
-- zp_ui_active for exactly this: ZPause installed, switched on, and running in
-- this match. For anybody else it is the state above.
A.IsAvailable = function ()
	if not CoD.isZombie then
		return false
	end
	if A.IsHost() then
		if Z.Get( "zp_ui_active" ) ~= "1" then
			return false
		end
		-- With zp_pause_menu on, opening this menu was the pause: the row
		-- would have read PAUSE GAME a moment before the game paused, and
		-- pressing it would resume. The menu is the button there.
		return Z.Get( "zp_ui_menu_pause" ) ~= "1"
	end
	local state = A.State()
	return state ~= nil and state.allowed and not state.menuPause
end

A.IsPaused = function ()
	if A.IsHost() then
		return Z.Get( "zp_ui_paused" ) == "1"
	end
	local state = A.State()
	return state ~= nil and state.paused
end

A.WatchState()

-- A press, sent twice on purpose. The menu response is the road the pause
-- menu already reports itself on; the request dvar is the one the public API
-- describes, and it is the road every setting on this screen already travels,
-- so it works wherever the rest of the page works. The script clears the dvar
-- as it serves it, which is what keeps two roads from being two pauses.
-- In a game the engine pauses by itself -- a solo one -- the pause menu holds
-- the world still for as long as it is open, and a pause laid on top of that
-- is a pause nothing can lift: the script is not running to be asked. So the
-- press leaves the game's own pause first and ZPause's takes over -- the menu
-- closes, the game runs, and what lands is the pause with the countdown, the
-- HUD and the resume everybody in the game shares. Resuming is the same the
-- other way round: the menu closes and the game carries on.
--
-- Co-op is left alone, because there the menu pauses nothing.
A.LeaveStockPause = function ( controller )
	local ok, engine = pcall( Engine.CanPauseGame )
	if not ok or engine ~= true then
		return false
	end
	local pauseMenu = CoD.ZPausePauseMenu
	if pauseMenu == nil or type( pauseMenu.Close ) ~= "function" then
		return false
	end
	return pauseMenu.Close( controller )
end

A.Request = function ( controller, what )
	if controller == nil or controller < 0 then
		return false
	end
	A.LeaveStockPause( controller )
	pcall( Engine.SendMenuResponse, controller, A.MENU, "request_" .. what )
	Z.Set( controller, "zp_ui_request", what )
	return true
end

A.RequestToggle = function ( controller )
	return A.Request( controller, "toggle" )
end

A.RequestPause = function ( controller )
	return A.Request( controller, "pause" )
end

A.RequestUnpause = function ( controller )
	return A.Request( controller, "unpause" )
end

-- The row itself, handed to whichever menu draws the shared list. It is one
-- press on the pause the mod already has and not a second implementation of
-- one: everything that decides a pause still decides this.
B.RegisterAction( {
	id = "zpause_toggle",
	owner = Z.Owner,
	ownerLabel = "ZPause",
	order = 10,
	-- Every player's: the script puts a press through the combo's gates.
	authority = "player",
	label = function ()
		if A.IsPaused() then
			return Z.Text( "ui.unpause_game", "UNPAUSE GAME" )
		end
		return Z.Text( "ui.pause_game", "PAUSE GAME" )
	end,
	hint = Z.Text( "ui.pause_game_hint", "Pause the game for everybody, the same as the pause combo does." ),
	visible = function ()
		return A.IsAvailable()
	end,
	action = function ( controller )
		A.RequestToggle( controller )
	end
} )

-- Who draws the shared rows. In a bundle every component's menu opens the
-- same screen and the same actions, so a row each would be the same row
-- four times: the first to load claims them, and a bundle's own loader
-- claims them ahead of everybody by setting these before anything else is
-- read. Standalone, ZPause claims them and draws them.
B.SettingsRowOwner = B.SettingsRowOwner or Z.Owner
B.ActionRowsOwner = B.ActionRowsOwner or Z.Owner

-- "zbundle" is the bundle's own claim: an aggregate's loader takes both rows for
-- the whole screen before any mod loads, and this renderer is the one that draws
-- them there, so it answers to that name as well as its own.
Z.DrawsSettingsRow = function ()
	return B.SettingsRowOwner == Z.Owner or B.SettingsRowOwner == "zbundle"
end

Z.DrawsActionRows = function ()
	return B.ActionRowsOwner == Z.Owner or B.ActionRowsOwner == "zbundle"
end

Z.TabLabel = function ( tab )
	local english = tab.labelText or tab.label
	if type( english ) ~= "string" or english == "" then
		english = tostring( tab.id or "" )
	end
	return Z.OwnerWords( english, nil, tab )
end

Z.TabHint = function ( tab )
	local english = tab.hintText or tab.hint
	if type( english ) ~= "string" then
		english = ""
	end
	return Z.OwnerWords( english, nil, tab )
end

Z.TabRows = function ( tab )
	if tab == nil then
		return {}
	end
	if type( tab.rows ) == "function" then
		local ok, rows = pcall( tab.rows )
		if ok and type( rows ) == "table" then
			tab.zpRowsFailed = nil
			return rows
		end
		-- A producer that threw is not an empty category, and the two look
		-- identical from here: an empty one greys out, which is right, while
		-- a broken one greys out and stays that way however the page is
		-- reopened. Said once per category rather than on every pass, since
		-- this is asked several times a second.
		if not tab.zpRowsFailed then
			tab.zpRowsFailed = true
			B.RowProducerErrors = B.RowProducerErrors or {}
			B.RowProducerErrors[tostring( tab.owner ) .. "/" .. tostring( tab.id )] = tostring( rows )
		end
		return {}
	end
	return type( tab.rows ) == "table" and tab.rows or {}
end

-- Whether the page will open a category: the registry's answer, and one of
-- the shell's own -- an empty CHANGED is nothing to walk into.
Z.TabEnabled = function ( tab, controller )
	if not B.TabEnabled( tab, controller ) then
		return false
	end
	if tab ~= nil and tab.role == "changed" then
		return #Z.TabRows( tab ) > 0
	end
	return true
end

-- The first category the page can actually open. Everything closed is
-- possible -- a standalone mod switched off with nothing changed -- and then
-- the first is shown as it is rather than the page coming up blank.
Z.FirstOpenTab = function ( tabs, controller )
	for _, tab in ipairs( tabs or {} ) do
		if Z.TabEnabled( tab, controller ) then
			return tab
		end
	end
	return ( tabs or {} )[1]
end

Z.FindTab = function ( tabs, id )
	for _, tab in ipairs( tabs or {} ) do
		if tab.id == id then
			return tab
		end
	end
	return nil
end

Z.FindTabIndex = function ( tabs, id )
	for index, tab in ipairs( tabs or {} ) do
		if tab.id == id then
			return index
		end
	end
	return 1
end

-- ------------------------------------------------------------------------
-- The lobby button
-- ------------------------------------------------------------------------

Z.IsHost = function ( controller )
	local ok, host = pcall( function ()
		local root = DataSources.LobbyRoot.getModel( controller )
		local model = nil
		if Engine.IsLobbyActive( Enum.LobbyType.LOBBY_TYPE_GAME ) then
			model = Engine.GetModel( root, "gameClient.isHost" )
		else
			model = Engine.GetModel( root, "privateClient.isHost" )
		end
		if model == nil then
			return 1
		end
		return Engine.GetModelValue( model )
	end )
	return ok and host == 1
end

-- In its own group, before the gum and build kit buttons every zombies lobby
-- ends with. One button, whoever drew it: in a bundle it opens everybody's
-- categories, so it is named for the screen rather than for ZPause.
Z.AddButton = function ( buttons, controller )
	local at = #buttons + 1
	for index, button in ipairs( buttons ) do
		if button.optionDisplay == "MENU_BUBBLEGUM_BUFFS_CAPS" then
			at = index
			break
		end
	end
	if at > 1 then
		buttons[at - 1].isLastButtonInGroup = true
	end
	table.insert( buttons, at, {
		optionDisplay = Z.MenuTitle( B.GetTabs( controller ) ),
		action = Z.OpenFromLobby,
		customId = "btnZPauseSettings",
		isLargeButton = true,
		isLastButtonInGroup = true,
		disabled = false,
		selected = false,
		warning = false
	} )
end

-- The zombies lobbies a host starts a game from: online, where solo games
-- start, private, and LAN.
Z.Hook = function ()
	if Z.hooked or CoD.LobbyMenus == nil or CoD.LobbyMenus.AddButtonsForTarget == nil or LobbyData == nil or LobbyData.UITargets == nil then
		return
	end
	Z.hooked = true
	Z.Lobbies = {}
	for _, name in ipairs( {
		"UI_ZMLOBBYONLINE",
		"UI_ZMLOBBYONLINECUSTOMGAME",
		"UI_ZMLOBBYLANGAME"
	} ) do
		local target = LobbyData.UITargets[name]
		if target ~= nil then
			Z.Lobbies[target.id] = true
		end
	end
	local addButtonsForTarget = CoD.LobbyMenus.AddButtonsForTarget
	CoD.LobbyMenus.AddButtonsForTarget = function ( controller, id )
		local buttons = addButtonsForTarget( controller, id )
		if Z.Lobbies[id] and Z.DrawsSettingsRow() and ( B.HostStatus ~= nil or Z.IsHost( controller ) ) then
			Z.AddButton( buttons, controller )
		end
		return buttons
	end
end

-- Opened the way the game opens its own bot settings from the lobby, so the
-- rest of the lobby sees the host is changing the rules.
Z.OpenFromLobby = function ( self, element, controller, param, menu )
	local host = B.HostStatus ~= nil and B.HostStatus( controller ) == "HOST"
		or B.HostStatus == nil and Z.IsHost( controller )
	if host then pcall( function ()
		CoD.LobbyBase.SetLeaderActivity( controller, CoD.LobbyBase.LeaderActivity.EDITING_GAME_RULES )
	end ) end
	local opened = OpenOverlay( menu, "ZPauseSettings", controller )
	if opened ~= nil then
		LUI.OverrideFunction_CallOriginalFirst( opened, "close", function ()
			if host then pcall( function ()
				CoD.LobbyBase.ResetLeaderActivity( controller )
			end ) end
		end )
	end
end

-- The other way in, from the game's own pause menu. A popup rather than an
-- overlay: the pause menu stays open underneath, the way its own options page
-- does, so stepping in here is not the menu closing and zp_pause_menu does
-- not read it as a resume.
Z.OpenFromPause = function ( self, element, controller )
	Z.Startup( controller )
	local menu = self
	while menu ~= nil and menu.openMenu == nil do
		menu = menu:getParent()
	end
	if menu ~= nil then
		OpenPopup( menu, "ZPauseInGameSettings", controller )
	end
end

-- ------------------------------------------------------------------------
-- The page
-- ------------------------------------------------------------------------

Z.Title = function ()
	return Z.Text( "ui.title", "ZPAUSE SETTINGS" )
end

-- ZPause's own name while ZPause is all there is on the page, and the
-- bundle's the moment somebody else has registered a tab: a screen carrying
-- four mods' settings is not ZPause's settings. The pause-menu row is named
-- from this as well -- one screen, one name, wherever it is opened from.
Z.MenuTitle = function ( tabs )
	if B.IsBundle() then
		return Z.Text( "ui.bundle_title", "ZBUNDLE SETTINGS" )
	end
	for _, tab in ipairs( tabs or {} ) do
		if tab.owner ~= Z.Owner and tab.owner ~= "zbundle" then
			return Z.Text( "ui.bundle_title", "ZBUNDLE SETTINGS" )
		end
	end
	return Z.Title()
end

Z.OwnerLabel = function ( tab )
	if tab ~= nil and tab.ownerLabel ~= nil and tab.ownerLabel ~= "" then
		return tostring( tab.ownerLabel )
	end
	return "ZPause"
end

-- And the line at the top, which names the owner of the category on screen:
-- with four mods' settings in one place, whose a category is should never be
-- something to work out from where it sits in the strip.
Z.TabTitle = function ( tab, tabs )
	local title = Z.MenuTitle( tabs )
	if tab == nil or title == Z.Title() then
		return title
	end
	if tab.role == "mods" then
		return title .. " - " .. Z.Shell( "MODS" )
	end
	if tab.role == "changed" then
		return title .. " - " .. Z.Shell( "CHANGED" )
	end
	return title .. " - " .. string.upper( Z.OwnerLabel( tab ) )
end

-- What the bundle calls itself, which it sets on the registry. Not on the
-- version line -- that line is the mods installed, and a bundle is not one of
-- them -- but part of the registry contract, and what a build reporting
-- itself somewhere else would use.
-- The dvar is the fallback for a build that has not set it.
Z.BundleVersion = function ()
	local value = B.BundleVersion or CoD.ZBundleVersion
	if type( value ) == "function" then
		local ok, result = pcall( value )
		value = ok and result or nil
	end
	if value == nil or value == "" then
		local dvar = Z.Get( "zbundle_version" )
		if dvar ~= "" then
			value = dvar
		end
	end
	return value
end

-- The image the Workshop build links into core_mod. BOIII and T7x read this
-- page out of ui_scripts, where there is no fastfile and so no way to
-- register an image of our own -- they get a half-transparent black panel
-- instead. One page, decided when it runs, rather than two pages to keep in
-- step.
--
-- The name is shared with Xep's other Black Ops III mods, which ship the same
-- artwork, so a bundle of them carries the image once.
Z.IMAGE = "zmods_menu_background_image"

Z.HasImage = function ()
	return B.BackgroundImageAvailable == true
end

Z.Backdrop = function ( menu )
	local background = LUI.UIImage.new()
	background:setLeftRight( true, true, 0, 0 )
	background:setTopBottom( true, true, 0, 0 )
	local hasBackgroundImage = Z.HasImage()
	if hasBackgroundImage then
		background:setImage( RegisterImage( Z.IMAGE ) )
	else
		background:setRGB( 0, 0, 0 )
		background:setAlpha( 0.5 )
	end
	menu:addElement( background )
	menu.Background = background

	-- Over the art, so a white list reads against it wherever the art is
	-- bright. The panel above is already dark enough on its own.
	local shade = LUI.UIImage.new()
	shade:setLeftRight( true, true, 0, 0 )
	shade:setTopBottom( true, true, 0, 0 )
	shade:setRGB( 0, 0, 0 )
	shade:setAlpha( hasBackgroundImage and 0.34 or 0 )
	menu:addElement( shade )
	menu.Shade = shade
end

-- What a row's setting currently holds. A tab somebody else registered
-- answers for its own; ours are dvars.
Z.RowGet = function ( row, tab )
	if tab ~= nil and type( tab.get ) == "function" then
		local ok, value = pcall( tab.get, row.dvar, row )
		if ok and value ~= nil then
			return tostring( value )
		end
	end
	return Z.Get( row.dvar )
end

-- An action row is a button: it holds no value, so it reads as empty and
-- counts as at its default -- never in CHANGED, never written by a reset, and
-- its owner's getter is never asked for a setting it does not have. Wrapped
-- around the two rather than written into them, and announced by
-- Z.NativeButtonRowSeam, so a bundle builder that still adds the same guard
-- finds its anchors and can switch to requiring this instead.
Z.NativeButtonRowSeam = 1
do
	local rowGet, isDefault = Z.RowGet, Z.IsDefault
	-- Named locals, so the two definitions above stay the only lines that
	-- spell either header: the builder that patches them counts its anchors.
	local function buttonRead ( row, tab )
		if row ~= nil and row.kind == "button" then
			return ""
		end
		return rowGet( row, tab )
	end
	local function buttonIsDefault ( current, row )
		if row ~= nil and row.kind == "button" then
			return true
		end
		return isDefault( current, row )
	end
	Z.RowGet = buttonRead
	Z.IsDefault = buttonIsDefault
end

-- The one way a value is written, whoever owns it.
Z.Apply = function ( controller, tab, row, value )
	if tab ~= nil and type( tab.set ) == "function" then
		tab.set( controller, row.dvar, value, row )
		return
	end
	-- A tab registered without a set of its own. Its dvar is still the live
	-- value and moving it is what the player asked for, but nothing of
	-- somebody else's goes into ZPause's save record -- a component that
	-- wants its change kept registers a set.
	Z.Set( controller, row.dvar, value )
end

-- Called by a row whenever one of its choices is under the cursor: as the
-- page opens, as the cursor moves onto the row, and as left or right moves
-- the choice. Only a move to a different value is a change, so opening a
-- page, scrolling it or hovering a row never writes anything.
-- The choice last put under the cursor on each row, for this session only.
-- A value equal to the row's default reads as DEFAULT everywhere else -- that
-- is what keeps an untouched row saying DEFAULT after a match has written
-- every default into its dvar -- but the selector itself has to stay on the
-- value the player moved to, or stepping across it snaps back to DEFAULT.
Z.Picked = Z.Picked or {}

Z.PickedKey = function ( row, tab )
	return tostring( tab ~= nil and tab.owner or "" ) .. "|" .. tostring( row.dvar or row.key or "" )
end

-- What was picked, and what the row read straight after the write. The second
-- is what the choice is matched against: an owner may store the default-equal
-- value as empty, or apply it a frame later, and the value picked is then not
-- what reads back.
Z.SetPicked = function ( row, tab, value, observed )
	if row == nil then return end
	Z.Picked[Z.PickedKey( row, tab )] = { value = value, observed = observed }
end

-- Forgotten when the menu opens and on every reset: a new screen, and a row
-- put back to DEFAULT, show DEFAULT again.
Z.ClearPicked = function ()
	Z.Picked = {}
end

-- True when the selector should rest on DEFAULT rather than on the value.
Z.ShowsDefault = function ( current, row, tab )
	local key = Z.PickedKey( row, tab )
	local picked = Z.Picked[key]
	-- The row has moved since, by somebody else or a reset: the pick no longer
	-- describes it, and is dropped whatever the row now reads.
	if picked ~= nil and not ( Z.Same( current, picked.observed ) or Z.Same( current, picked.value ) ) then
		Z.Picked[key] = nil
		picked = nil
	end
	if not Z.IsDefault( current, row ) then
		return false
	end
	if picked == nil then
		return true
	end
	return picked.value == nil or picked.value == ""
end

Z.Chosen = function ( self, element, controller, param, menu )
	local row = param.row or param
	local tab = param.tab
	if not Z.Writable( row, tab, controller ) then return end
	UpdateInfoModels( element )
	-- Which choice is under the cursor, DEFAULT or a value, so the rebuild
	-- that follows keeps it there: a value that happens to equal the row's
	-- default would otherwise come back as DEFAULT.
	local picked = element.default == true and "" or element.value
	local current = Z.RowGet( row, tab )
	Z.SetPicked( row, tab, picked, current )
	if element.default == true then
		if Z.IsDefault( current, row ) then
			return
		end
	elseif Z.Same( current, element.value ) then
		return
	end
	Z.Apply( controller, tab, row, element.value )
	Z.SetPicked( row, tab, picked, Z.RowGet( row, tab ) )

	-- Anything that got this far is a real write: hovering a row and
	-- stopping on the value it already had both returned above.
	--
	-- So the category strip is rebuilt, whatever was written. CHANGED is a
	-- category whose very existence depends on some setting differing from
	-- its default, and it is somebody else's category -- the first edit has
	-- to open it and the last reset has to close it, there and then, without
	-- a tab switch or a reopen. A mod switched off on MODS loses its
	-- categories the same way, and a setting other rows depend on greys them.
	-- One rebuild covers all three, and it is queued rather than done here:
	-- the rows this selector sits in are what would be rebuilt underneath it.
	Z.QueueRefreshTabs( menu, controller, tab ~= nil and tab.id or nil )
end

-- One rebuild, after the press that asked for it has finished. A second
-- request before it runs moves the one already queued rather than adding
-- another; a game with no timer to give runs it now, which is still after
-- the callback that asked.
Z.QueueRefreshTabs = function ( menu, controller, preferredId )
	if menu == nil then
		return
	end
	menu.zpPendingController = controller
	menu.zpPendingTabId = preferredId
	if menu.zpRefreshQueued == true then
		return
	end
	menu.zpRefreshQueued = true

	local refresh = function ()
		menu.zpRefreshQueued = nil
		local who = menu.zpPendingController or controller
		local id = menu.zpPendingTabId or preferredId
		menu.zpPendingController = nil
		menu.zpPendingTabId = nil
		Z.RefreshTabs( menu, who, id )
	end

	-- 50 ms, not a tick: a one-millisecond timer fires while the overlay is
	-- still on its way out on T7x, and the rebuild lands on the page as it
	-- was. Requests that arrive in the meantime move this one rather than
	-- adding another, so a batch is one rebuild however it was asked for.
	local ok, timer = pcall( LUI.UITimer.newElementTimer, 50, true, refresh )
	if ok and timer ~= nil then
		menu:addElement( timer )
	else
		refresh()
	end
end

-- Y, or F on a keyboard: the category with everything at its default taken
-- out of it. For a long category where one setting has been moved and the
-- host wants to see which. Off again on the next press and whenever the
-- category changes, so it is never a page quietly showing half of itself.
--
-- The system categories are left alone: CHANGED is already this, and MODS is
-- four rows.
Z.ToggleChangedFilter = function ( controller, menu )
	if menu == nil or menu.Options == nil then
		return
	end
	local tab = menu.zpTab
	if tab == nil or tab.role ~= nil then
		return
	end
	menu.zpChangedOnly = not menu.zpChangedOnly
	local rows = Z.TabRows( tab )
	if menu.zpChangedOnly then
		local filtered = {}
		for _, row in ipairs( rows ) do
			if not Z.IsDefault( Z.RowGet( row, tab ), row ) then
				table.insert( filtered, row )
			end
		end
		rows = filtered
	end
	menu.zpRows = rows
	Z.BuildRows( menu.zpSource, rows, tab, controller )
	menu.Options:setDataSource( menu.zpSource )
	menu.Subtitle:setText( Z.TabHint( tab )
		.. ( menu.zpChangedOnly and "  " .. Z.Text( "ui.filter_changed_on", "FILTER: CHANGED" ) or "" ) )
	Z.SyncScrollbar( menu )
	if #rows == 0 then
		Z.ShowEmpty( menu )
	end
end

-- The categories as they now stand, for the one page that can change which
-- there are. Every category is given its rows again, since a component coming
-- back has none yet and the MODS page itself has just moved.
--
-- The strip is rebuilt under a name the game has not seen: Black Ops III keeps
-- a grid's item count against its data source's name, so handing back the old
-- name leaves the strip the length it used to be -- a category removed still
-- taking up a cell, or one restored with nowhere to go.
Z.RefreshTabs = function ( menu, controller, preferredId )
	if menu == nil or menu.Tabs == nil or menu.zpMenuName == nil then
		return
	end
	local tabs = B.GetTabs( controller )
	local active = Z.FindTab( tabs, preferredId or menu.zpTabId )
	if active ~= nil and not Z.TabEnabled( active, controller ) then
		active = nil
	end
	active = active or Z.FirstOpenTab( tabs, controller )
	if active == nil then
		return
	end
	menu.zpTabs = tabs
	-- A mod switched off is still installed and still on the line.
	if menu.ComponentVersions ~= nil then
		menu.ComponentVersions:setText( B.ComponentVersionsText( controller ) )
	end
	for _, tab in ipairs( tabs ) do
		local source = menu.zpSourcePrefix .. tab.id
		menu.zpSources[tab.id] = source
		Z.BuildRows( source, Z.TabRows( tab ), tab, controller )
	end
	menu.zpRegistryRevision = ( menu.zpRegistryRevision or 0 ) + 1
	menu.zpTabSource = menu.zpMenuName .. "TabsLive_" .. tostring( menu.zpRegistryRevision )
	Z.BuildTabs( menu.zpTabSource, tabs, active.id, controller )
	menu.Tabs.grid:setDataSource( menu.zpTabSource )
	if menu.Tabs.grid.updateDataSource ~= nil then
		menu.Tabs.grid:updateDataSource()
	end
	Z.ShowTab( menu, controller, active.id, true )
	Z.UpdateTabNavigation( menu, active.id, controller )
end

-- The game marks a setting that is not at its default; DEFAULT is the one
-- choice that is.
-- The action row under the cursor, pressed.
--
-- An action row has no value to cycle, so the ordinary left/right road into
-- a row never reaches it: it is activated instead, and this is what every
-- road into an activation goes through. `control` is a widget a mouse was
-- clicked on; without one it is whatever the list has focused.
--
-- Returns true when it was an action row, so a caller can fall back to its
-- own behaviour for an ordinary setting.
Z.ButtonRowAt = function ( menu, controller, control )
	if menu == nil or menu.Options == nil then
		return false
	end
	local index = nil
	if control ~= nil then
		local item = control
		while item ~= nil and item ~= menu.Options do
			local parent = item:getParent()
			if parent == menu.Options then
				index = item.gridInfoTable ~= nil and item.gridInfoTable.zeroBasedIndex or nil
				break
			end
			item = parent
		end
		if index == nil then
			return false
		end
	else
		-- The row that has focus now, and nothing else: an old list
		-- selection is not a press on anything, and firing it ran an action
		-- the player was no longer on.
		local active = menu.Options.activeWidget
		if active == nil or active.gridInfoTable == nil or active.gridInfoTable.zeroBasedIndex == nil then
			return false
		end
		index = active.gridInfoTable.zeroBasedIndex
	end
	local row = ( menu.zpRows or {} )[index + 1]
	if row == nil or row.kind ~= "button" then
		return false
	end
	local tab = menu.zpTab
	-- Rechecked here as well as when the row was drawn: a mod can switch its
	-- own action off, and host status can change with the page open. The row
	-- is still swallowed, because it is still an action row -- it just does
	-- nothing.
	if not B.RowUnavailable( row, tab, controller ) and type( row.action ) == "function" then
		pcall( row.action, controller, menu, row, tab )
	end
	return true
end

-- The value the details panel shows beside its caption, and the caption.
--
-- Three things can stand there and only one of them is the default. A row the
-- host owns and this player does not shows that it cannot be read; a row its
-- owner is holding shows the value it is held to; a row switched off by
-- another setting shows what it is actually sitting at, which is not
-- necessarily its default. Showing DEFAULT over any of those names the wrong
-- thing, and for a row whose default is OFF and whose value is ON it is also
-- the opposite of what is true.
Z.DetailsValue = function ( row, tab, controller )
	if row == nil then
		return "", Z.Text( "ui.default", "DEFAULT" )
	end
	local hostValue = B.RowHostValue ~= nil and B.RowHostValue( row, tab, controller ) or nil
	if hostValue ~= nil then
		return Z.Shell( hostValue ), Z.Text( "ui.host", "HOST" )
	end
	-- RowOverride gives value first, locked second. RowForced gives them the
	-- other way round; reading either in the wrong order is how a forced row
	-- ends up showing its default.
	local forced, locked = nil, false
	if B.RowOverride ~= nil then
		forced, locked = B.RowOverride( row, tab, controller )
	end
	if locked then
		return Z.ValueLabel( row, forced, tab, controller ), Z.Text( "ui.forced", "FORCED" )
	end
	if B.RowWritable ~= nil and not B.RowWritable( row, tab, controller )
		and #( row.values or {} ) > 0 then
		return Z.ValueLabel( row, Z.RowGet( row, tab ), tab, controller ), Z.Text( "ui.current", "CURRENT" )
	end
	return Z.DefaultLabel( row, tab, controller ), Z.Text( "ui.default", "DEFAULT" )
end

-- A value as the row writes it, rather than as it is stored. An empty one is
-- the default, which has a label of its own.
Z.ValueLabel = function ( row, value, tab, controller )
	if value == nil or value == "" then
		return Z.DefaultLabel( row, tab, controller )
	end
	for index, listed in ipairs( row.values or {} ) do
		if Z.Same( listed, value ) then
			return Z.ChoiceLabel( row, index, tab, controller ) or string.upper( tostring( listed ) )
		end
	end
	return string.upper( tostring( value ) )
end

Z.ShowChange = function ( item )
	return item.default ~= true
end

-- One setting. DEFAULT is the empty value, and it stands for the default
-- itself. A value the page does not step through keeps a choice of its own
-- rather than showing as another.
Z.Row = function ( row, source, tab, controller )
	-- Built fresh for every request. LUIGridLayout takes selectIndex out of
	-- the table it is handed while it prepares a list, so handing the same
	-- table back a second time loses the selected value -- which snapped a
	-- row to DEFAULT as soon as scrolling recycled it.
	-- The controller this row is being drawn for, which is not always the
	-- primary one: a second pad opening the page gets its own data sources,
	-- and a personal row's own predicate answers differently for it. The
	-- stock ListSetup callback is handed that controller; using Z.Who()
	-- instead drew a live row for somebody who may not write it.
	local build = function ( buildFor )
		local who = buildFor or controller or who
		-- An action row is a button, not a setting: no values, nothing
		-- stored, and nothing to cycle. ZPause registers none of its own,
		-- but this renderer draws the whole bundle's categories, so another
		-- mod's button has to work on it. The row contract asks for the
		-- native row layout with one ACTIVATE control and no arrows, which
		-- is a single option whose action is the row's.
		if row ~= nil and row.kind == "button" then
			local options = {}
			local offNow = B.RowUnavailable( row, tab, who )
			table.insert( options, {
				models = {
					text = Z.Text( "ui.activate", "ACTIVATE" ),
					-- A button nobody here may press reads as one of the
					-- greyed rows rather than as a live one that does
					-- nothing when it is pressed.
					zbRowState = offNow and "DISABLED" or "",
					-- Always: an action row has nothing to cycle, so its
					-- arrows are never anything but a lie.
					zbOptionLocked = true
				},
				properties = {
					title = row.dvar or "",
					desc = Z.RowHint( who, row, tab ) or "",
					value = "",
					default = false,
					selectIndex = true,
					first = true,
					last = true,
					loopEdges = false
					-- No action, deliberately. The stock slider dispatches
					-- ProcessListAction from list_item_gain_focus, so an
					-- option carrying one runs when the cursor merely
					-- arrives on the row -- and it arrives again on every
					-- rebuild and every recycled widget. A button wired this
					-- way fires by being looked at, which is how hovering
					-- ZStats' reset button kept triggering it.
					--
					-- Z.ButtonRowAt is the only road in: Enter, A, or a
					-- click on the row, each naming the row it meant, and
					-- each rechecking availability at the moment of the
					-- press.
				}
			} )
			return options
		end
		-- A mod's own switch shows the switch and nothing else. The name
		-- behind it is a row id rather than a setting anybody has, so there
		-- is no default to fall back to and nothing to read out of a dvar:
		-- ON and OFF are the whole of it, and the component's own callback
		-- is what says which.
		--
		-- Only where this player may actually write it. A client, or anybody
		-- whose host status is not known yet, falls through to the inert
		-- branch below and gets the one honest unavailable choice instead:
		-- the write was always refused, but a row offering live arrows and
		-- then declining to move is the page telling them otherwise.
		if tab ~= nil and tab.role == "mods" and Z.Writable( row, tab, who ) then
			local live = Z.RowGet( row, tab )
			local options = {}
			for index, value in ipairs( row.values or {} ) do
				table.insert( options, {
					models = {
						text = Z.ChoiceLabel( row, index, tab, who ) or string.upper( tostring( value ) ),
						zbRowState = "",
						zbOptionLocked = false
					},
					properties = {
						title = row.dvar or "",
						desc = Z.RowHint( who, row, tab ) or "",
						value = value,
						default = false,
						actionParam = { row = row, tab = tab },
						action = Z.Chosen,
						selectIndex = Z.Same( live, value ),
						loopEdges = true,
						defaultText = Z.ValueLabel( row, live, tab, who ),
						defaultCaption = Z.Text( "ui.current", "CURRENT" ),
						boundaryText = Z.StatusText( row, tab, who ),
						scopeText = Z.Scope( row, tab, who ),
						dvarText = row.dvar or ""
					}
				} )
			end
			if #options > 0 then
				options[1].properties.first = true
				options[#options].properties.last = true
			end
			return options
		end

		local current = Z.RowGet( row, tab )
		local atDefault = Z.IsDefault( current, row )
		local listed = atDefault
		for _, value in ipairs( row.values or {} ) do
			if Z.Same( current, value ) then
				listed = true
			end
		end

		local options = {}
		-- What the row is, for the widget: greyed and arrowless while it is
		-- switched off or held to a value, ordinary otherwise. Set on every
		-- option because a control item is recycled between rows and reads
		-- whichever one it has been handed.
		local state = ""
		if B.RowForced( row, tab, who ) then
			state = "OVERRIDDEN"
		elseif not Z.Writable( row, tab, who ) then
			state = "DISABLED"
		end
		local add = function ( label, value, isDefault, selected )
			table.insert( options, {
				models = {
					text = label,
					zbRowState = state,
					zbOptionLocked = state ~= ""
				},
				properties = {
					title = row.dvar or "",
					desc = Z.RowHint( who, row, tab ) or "",
					value = value,
					default = isDefault,
					actionParam = {
						row = row,
						tab = tab
					},
					action = Z.Chosen,
					selectIndex = selected,
					loopEdges = true,
					showChangeIndicator = Z.ShowChange
				}
			} )
		end

		-- A row another setting has switched off, and somebody else's
		-- report line with it: one choice, the value it already has, and
		-- nothing wired to it. The branch belongs here rather than only in
		-- the bulk actions, because a list that adds DEFAULT and then every
		-- value still lets an inert row cycle through them on screen.
		if not Z.Writable( row, tab, who ) then
			-- A locked row shows what it is held at, not what is saved
			-- behind it; a disabled or informational one shows what it has.
			local locked, forced = CoD.ZBundleSettings.RowForced( row, tab, who )
			local held = current
			if locked and forced ~= nil then
				held = forced
			end

			-- Only a bare value is upper-cased. Words have already been through
			-- their owner's provider and are uppercase in every language, and
			-- string.upper works on bytes: under a C runtime locale that is not
			-- "C" it rewrites UTF-8 - VERFÜGBAR came out VERFÌGBAR.
			local hostValue = B.RowHostValue ~= nil and B.RowHostValue( row, tab, who ) or nil
			local shown = hostValue ~= nil and Z.Shell( hostValue ) or string.upper( tostring( held ) )
			if hostValue ~= nil then
				-- A local saved preference is not evidence of the host's live value.
			elseif not locked and atDefault then
				shown = Z.DefaultLabel( row, tab, who )
			else
				for index, value in ipairs( row.values or {} ) do
					if Z.Same( held, value ) then
						shown = Z.ChoiceLabel( row, index, tab, who ) or string.upper( tostring( value ) )
						break
					end
				end
			end

			-- Which of the three it is, said on the row itself, since the
			-- arrows are gone and one value on its own reads as a setting
			-- that simply has one.
			shown = tostring( shown )
			if hostValue ~= nil then
			elseif locked then
				shown = Z.Format( "ui.locked_value", "LOCKED: {value}", { value = shown } )
			elseif row.disabledReason ~= nil or row.enabled ~= nil then
				shown = Z.Format( "ui.disabled_value", "DISABLED: {value}", { value = shown } )
			end

			add( shown, held, hostValue == nil and not locked and atDefault, true )
			options[1].properties.action = nil
			options[1].properties.actionParam = nil
			options[1].properties.loopEdges = false
			options[1].properties.showChangeIndicator = nil
			options[1].properties.first = true
			options[1].properties.last = true
			return options
		end

		-- Every value, including the one this build's default happens to
		-- be. It used to be left out, on the grounds that picking it by
		-- value would stop it following the default -- but the row is
		-- built into the mod and the installer's config editor cannot
		-- rewrite it, so once the editor had moved a default the old value
		-- was gone from the page: configure zp_vote on and this offered
		-- DEFAULT (now on) and ON, with no way to turn voting off. DEFAULT
		-- still saves nothing and still follows whatever the script
		-- carries.
		local onDefault = Z.ShowsDefault( current, row, tab )
		add( Z.Text( "ui.default", "DEFAULT" ), "", true, onDefault )
		for index, value in ipairs( row.values or {} ) do
			if not listed and row.kind == "number" and tonumber( current ) ~= nil and tonumber( current ) < tonumber( value ) then
				add( current, current, false, true )
				listed = true
			end
			add( Z.ChoiceLabel( row, index, tab, who ) or value, value, false, not onDefault and Z.Same( current, value ) )
		end
		if not listed then
			add( string.upper( current ), current, false, true )
		end
		options[1].properties.first = true
		options[#options].properties.last = true
		return options
	end

	DataSources[source] = DataSourceHelpers.ListSetup( source, build, nil, nil, nil )
	local who = controller or Z.Who()
	return {
		models = {
			name = Z.RowLabel( row, tab, who ),
			dvarText = row.dvar or "",
			desc = Z.RowHint( who, row, tab ) or "",
			defaultText = ( Z.DetailsValue( row, tab, who ) ),
			-- What that line is showing, since it is not always the default:
			-- CURRENT where the owner is holding the row to a value, and
			-- HOST where the host's own value is the thing that cannot be
			-- read. A caption that said DEFAULT over either would be naming
			-- the wrong thing.
			defaultCaption = select( 2, Z.DetailsValue( row, tab, who ) ),
			boundaryText = Z.StatusText( row, tab, who ),
			scopeText = Z.Scope( row, tab, who ),
			optionsDatasource = source
		},
		properties = {}
	}
end

-- One outer data source per tab, never one shared between them: T7x keeps a
-- data source alive past the menu that made it, so a shorter tab reusing a
-- longer one's source inherits its row count and shows a scrollbar for rows
-- that are not there.
Z.BuildRows = function ( name, rows, tab, controller )
	DataSources[name] = DataSourceHelpers.ListSetup( name, function ( listFor )
		local items = {}
		local who = listFor or controller
		for index, row in ipairs( rows ) do
			table.insert( items, Z.Row( row, name .. "_" .. index, tab, who ) )
		end
		return items
	end, nil, nil, nil )
end

-- One step of the strip. The grid is moved rather than sent a synthetic key
-- -- a callback against LUI_KEY_NONE is not dispatched reliably on PC -- and
-- moved one cell at a time until the page is on the category the arrows say
-- is next: stock skips a cell marked disabled, and some T7x builds do not, so
-- this stops when the page has actually moved rather than after one press.
Z.NavigateTab = function ( menu, tabs, controller, direction )
	if menu == nil or tabs == nil or tabs.grid == nil then
		return false
	end
	local target = Z.AdjacentTabIndex( menu.zpTabs, menu.zpTabId, direction, controller )
	if target == nil then
		return false
	end
	-- Going round the end of the strip. The grid stops at its last cell and
	-- navigateItemLeft/Right will not take it further, so the far category
	-- is reached by rebuilding the strip on it rather than by walking.
	local current = Z.FindTabIndex( menu.zpTabs, menu.zpTabId )
	if ( direction < 0 and target > current ) or ( direction > 0 and target < current ) then
		Z.RefreshTabs( menu, controller, menu.zpTabs[target].id )
		return true
	end
	local id = menu.zpTabs[target].id
	for _ = 1, #menu.zpTabs do
		if direction < 0 then
			tabs.grid:navigateItemLeft()
		else
			tabs.grid:navigateItemRight()
		end
		if menu.zpTabId == id then
			return true
		end
	end
	return false
end

Z.BuildTabs = function ( name, tabs, selected, controller )
	DataSources[name] = DataSourceHelpers.ListSetup( name, function ()
		local items = {}
		for _, tab in ipairs( tabs ) do
			table.insert( items, {
				models = {
					tabName = Z.TabLabel( tab ),
					tabId = tab.id,
					tabHint = Z.TabHint( tab ),
					tabOwner = tab.owner or "",
					-- What greys the cell and what the grid's own navigation
					-- steps over.
					disabled = not Z.TabEnabled( tab, controller )
				},
				properties = {
					selectIndex = tab.id == selected
				}
			} )
		end
		return items
	end, nil, nil, nil )
end

-- The stock scrollbar caches the height it was built with, and a data source
-- outlives the menu that made it on T7x, so a longer tab could leave a
-- misleading thumb behind on a shorter one. Both are told the truth again
-- every time a tab is shown.
Z.SyncScrollbar = function ( menu )
	if menu == nil or menu.Options == nil then
		return
	end
	menu.Options.vCount = 7
	menu.Options.requestedRowCount = #menu.zpRows
	if menu.Options.verticalScrollbar ~= nil then
		local _, height = menu.Options:getLocalSize()
		if height ~= nil and height > 24 then
			menu.Options.verticalScrollbar.sliderTop = 12
			menu.Options.verticalScrollbar.sliderHeight = height - 24
		end
	end
	menu.Options:updateScrollbars()
end

-- What lies either side of the tab under the cursor, and where it is in the
-- run. Six cells are visible at a time and there can be more than six tabs,
-- so without this a player has no way of knowing the rest are there.
-- What the arrows move to, which is not always the cell next door: a
-- category closed by its mod being switched off is stepped over.
Z.AdjacentTabIndex = function ( tabs, id, direction, controller )
	local count = #( tabs or {} )
	if count < 2 then
		return nil
	end
	local index = Z.FindTabIndex( tabs, id )
	for _ = 1, count - 1 do
		index = index + direction
		-- The strip wraps, as Black Ops II's does: back from the first
		-- category is the last one and past the last is the first. Stopping
		-- at the ends instead hides an arrow on a short strip, which reads
		-- as there being nothing further rather than as having gone round.
		if index < 1 then
			index = count
		elseif index > count then
			index = 1
		end
		if Z.TabEnabled( tabs[index], controller ) then
			return index
		end
	end
	return nil
end

Z.UpdateTabNavigation = function ( menu, id, controller )
	if menu == nil or menu.zpTabs == nil then
		return
	end
	local count = #menu.zpTabs
	local index = Z.FindTabIndex( menu.zpTabs, id )
	local previousIndex = Z.AdjacentTabIndex( menu.zpTabs, id, -1, controller )
	local nextIndex = Z.AdjacentTabIndex( menu.zpTabs, id, 1, controller )
	local hasPrevious = previousIndex ~= nil
	local hasNext = nextIndex ~= nil
	-- The strip wraps, so both arrows are lit wherever there is a second
	-- category to reach. They dim only on a strip with nowhere else to go,
	-- which is a bundle with one mod and everything else switched off.
	if menu.TabLeft ~= nil then
		menu.TabLeft:setAlpha( hasPrevious and 1 or 0.22 )
	end
	if menu.TabRight ~= nil then
		menu.TabRight:setAlpha( hasNext and 1 or 0.22 )
	end
	if menu.TabPrevious ~= nil then
		menu.TabPrevious:setText( hasPrevious
			and "<  " .. Z.Text( "ui.prev", "PREV" ) .. ": " .. Z.TabLabel( menu.zpTabs[previousIndex] )
			or "" )
	end
	if menu.TabNext ~= nil then
		menu.TabNext:setText( hasNext
			and Z.Text( "ui.next", "NEXT" ) .. ": " .. Z.TabLabel( menu.zpTabs[nextIndex] ) .. "  >"
			or "" )
	end
	if menu.TabPosition ~= nil then
		menu.TabPosition:setText( Z.Text( "ui.category", "CATEGORY" ) .. " "
			.. tostring( index ) .. " / " .. tostring( count ) )
	end
end

-- Everything about the rows on screen, as one value to compare against.
--
-- Another mod's rows can change what they are while this page is open -- a
-- setting of theirs switching one of their own rows off, a host status that
-- has just resolved -- and nothing tells this page about it. So it looks,
-- twice a second, at a string rather than at each row in turn.
Z.AvailabilityFingerprint = function ( menu, controller )
	local parts = {}
	for index, row in ipairs( menu.zpRows or {} ) do
		parts[index] = tostring( row.dvar or index ) .. ":"
			.. tostring( B.RowAvailabilityStamp( row, menu.zpTab, controller ) )
	end
	return table.concat( parts, "|" )
end

Z.AttachAvailabilityWatch = function ( menu, controller )
	if menu == nil or menu.zpAvailabilityTimer ~= nil then
		return
	end
	menu.zpAvailabilityTabId = menu.zpTabId
	menu.zpAvailabilityPrint = Z.AvailabilityFingerprint( menu, controller )
	local ok, timer = pcall( LUI.UITimer.newElementTimer, 250, false, function ()
		-- Not while a confirmation is over it, and not while the page is
		-- not taking input: a rebuild underneath either is a page moving
		-- on its own.
		if menu.occludedBy ~= nil or menu.m_inputDisabled or menu.zpTab == nil then
			return
		end
		local print = Z.AvailabilityFingerprint( menu, controller )
		if menu.zpAvailabilityTabId ~= menu.zpTabId then
			-- A different category: this is its first reading, not a change.
			menu.zpAvailabilityTabId = menu.zpTabId
			menu.zpAvailabilityPrint = print
		elseif print ~= menu.zpAvailabilityPrint then
			menu.zpAvailabilityPrint = print
			Z.QueueRefreshTabs( menu, controller, menu.zpTabId )
		end
	end )
	if ok and timer ~= nil then
		menu.zpAvailabilityTimer = timer
		menu:addElement( timer )
	end
end

-- Hold a bumper, or Q or E, and the strip keeps going.
--
-- This page owns every step of the strip: the press itself is the first, then
-- 350 ms, then one every 225 ms until the key comes up -- long enough that a
-- tap is never two, short enough that fifteen categories is a hold rather than
-- fifteen presses. The stock tab list is told not to navigate, the LB/RB
-- callbacks are inert, and the four inputs that move it are read where a
-- key-down and a key-up can be told apart. It is the Z mods' shared menu kit's
-- route, the one Xep confirmed on 12 October 2026: the one before it let the
-- stock strip take the first step and this page the rest, and two owners of
-- one strip is how a held key came to skip a category or stall.
Z.StopTabHold = function ( menu )
	if menu == nil then
		return
	end
	menu.zpTabHoldSource = nil
	menu.zpTabHoldDirection = nil
	menu.zpTabHoldEpoch = ( menu.zpTabHoldEpoch or 0 ) + 1
	if menu.zpTabHoldTimer ~= nil then
		pcall( menu.zpTabHoldTimer.close, menu.zpTabHoldTimer )
		menu.zpTabHoldTimer = nil
	end
end

Z.TabHoldBlocked = function ( menu )
	return menu == nil or menu.occludedBy ~= nil
end

-- One timer at a time, armed again after each step rather than left
-- repeating, so a step that rebuilt the strip has finished before the next.
Z.TabHoldSchedule = function ( menu, epoch, delay, controller, direction )
	local ok, timer = pcall( LUI.UITimer.newElementTimer, delay, true, function ()
		menu.zpTabHoldTimer = nil
		if menu.zpTabHoldEpoch ~= epoch or menu.zpTabHoldSource == nil then
			return
		end
		if Z.TabHoldBlocked( menu ) or not Z.NavigateTab( menu, menu.Tabs, controller, direction ) then
			Z.StopTabHold( menu )
			return
		end
		if menu.zpTabHoldEpoch == epoch then
			Z.TabHoldSchedule( menu, epoch, 225, controller, direction )
		end
	end )
	if ok and timer ~= nil then
		menu.zpTabHoldTimer = timer
		menu:addElement( timer )
	else
		Z.StopTabHold( menu )
	end
end

Z.StartTabHold = function ( menu, controller, direction, source )
	if menu == nil or Z.TabHoldBlocked( menu ) then
		return
	end
	if menu.zpTabHoldSource == source and menu.zpTabHoldDirection == direction then
		return
	end
	Z.StopTabHold( menu )
	menu.zpTabHoldSource = source
	menu.zpTabHoldDirection = direction
	local epoch = menu.zpTabHoldEpoch
	-- The press is the first step.
	local moved = Z.NavigateTab( menu, menu.Tabs, controller, direction )
	if menu.zpTabHoldEpoch ~= epoch then
		return
	end
	if not moved or Z.TabHoldBlocked( menu ) then
		Z.StopTabHold( menu )
		return
	end
	Z.TabHoldSchedule( menu, epoch, 350, controller, direction )
end

-- One edge state per input, merging the two roads it arrives on: the raw
-- gamepad_button event and the input's model. A real raw release wins, so a
-- model still reading down afterwards cannot start the hold again.
Z.TabHoldEdge = function ( menu, controller, source, direction, route, down )
	if menu == nil or type( down ) ~= "boolean" then
		return
	end
	menu.zpTabEdges = menu.zpTabEdges or {}
	local state = menu.zpTabEdges[source]
	if state == nil then
		state = {}
		menu.zpTabEdges[source] = state
	end
	if state[route] == down then
		return
	end
	state[route] = down
	if route == "raw" then
		state.rawSeen = down
	end
	if not down and ( route == "raw" or not state.rawSeen ) then
		state.pressed = false
		if menu.zpTabHoldSource == source then
			Z.StopTabHold( menu )
		end
	elseif down and not state.pressed then
		state.pressed = true
		Z.StartTabHold( menu, controller, direction, source )
	end
end

Z.TabHoldSources = {
	Q = -1,
	E = 1,
	LB = -1,
	RB = 1
}

-- Stock HandleButtonPress runs a key's callbacks and then clears its model to
-- zero -- an acknowledgement, not the key coming up -- so a held Q read as
-- released the instant it was acted on, and the stock tab list's own callback
-- took a step of its own. For this page's four strip inputs it only reads the
-- model: the step is this page's, and the model keeps the real state.
Z.InstallHeldShortcutBitGuard = function ()
	if CoD.Menu == nil or type( CoD.Menu.HandleButtonPress ) ~= "function"
		or Z.HeldShortcutHandler == CoD.Menu.HandleButtonPress then
		return
	end
	local inherited = CoD.Menu.HandleButtonPress
	local wrapped = function ( menu, controller, button, model, ... )
		local models = menu ~= nil and menu.zpHeldShortcutModels or nil
		local source = models ~= nil and models[model] or nil
		if source == nil then
			return inherited( menu, controller, button, model, ... )
		end
		Z.TabHoldModel( menu, controller, source, model )
	end
	Z.HeldShortcutHandler = wrapped
	CoD.Menu.HandleButtonPress = wrapped
end

Z.TabHoldModel = function ( menu, controller, source, model )
	local usable = Engine.IsControllerBeingUsed( controller ) or menu.unusedControllerAllowed
	local down = false
	if usable then
		local ok, got = pcall( function ()
			return CoD.BitUtility.IsBitwiseAndNonZero( Engine.GetModelValue( model ), Enum.LUIButtonFlags.FLAG_DOWN )
		end )
		down = ok and got == true
	end
	Z.TabHoldEdge( menu, controller, source, Z.TabHoldSources[source], "model", down )
end

Z.AttachTabHold = function ( menu, controller )
	if menu == nil or menu.TabLeft == nil or menu.TabRight == nil then
		return
	end
	Z.AttachAvailabilityWatch( menu, controller )

	-- The stock strip never steps on its own: basicTabList's LB/RB callbacks
	-- read this flag.
	if menu.Tabs ~= nil then
		menu.Tabs.m_disableNavigation = true
	end

	-- The arrows themselves, for a mouse. A press moves one category and
	-- starts the hold; letting go or leaving the button ends it. The stock
	-- button_action still fires after a click, and would move a second
	-- category, so the press marks the element and that one is swallowed.
	local attachMouse = function ( button, direction )
		local source = direction < 0 and "mouse_left" or "mouse_right"
		button:registerEventHandler( "leftmousedown", function ( element, event )
			element.zpMouseTabPress = true
			Z.StartTabHold( menu, event.controller or controller, direction, source )
			return true
		end )
		button:registerEventHandler( "leftmouseup", function ()
			if menu.zpTabHoldSource == source then
				Z.StopTabHold( menu )
			end
			return true
		end )
		button:registerEventHandler( "mouseleave", function ()
			if menu.zpTabHoldSource == source then
				Z.StopTabHold( menu )
			end
		end )
		button:registerEventHandler( "button_action", function ( element, event )
			if element.zpMouseTabPress then
				element.zpMouseTabPress = nil
				return true
			end
			Z.NavigateTab( menu, menu.Tabs, event ~= nil and event.controller or controller, direction )
			return true
		end )
	end
	attachMouse( menu.TabLeft, -1 )
	attachMouse( menu.TabRight, 1 )

	-- Q, E and both bumpers, read from their models: the only place a release
	-- is published.
	menu.zpHeldShortcutModels = {}
	local root = Engine.GetModelForController( controller )
	for source, path in pairs( {
		Q = "KeyPressBits.Q",
		E = "KeyPressBits.E",
		LB = "ButtonBits." .. Enum.LUIButton.LUI_KEY_LB,
		RB = "ButtonBits." .. Enum.LUIButton.LUI_KEY_RB
	} ) do
		local ok, model = pcall( Engine.GetModel, root, path )
		if ok and model ~= nil then
			menu.zpHeldShortcutModels[model] = source
			menu:subscribeToModel( model, function ( changed )
				Z.TabHoldModel( menu, controller, source, changed )
			end, false )
		end
	end

	-- The same four as raw events, for a keyboard or pad that does not publish
	-- bits. Consumed whatever happens: a press that fell through would be a
	-- second step. Anything else goes on to whatever was there before.
	local previous = menu.m_eventHandlers ~= nil and menu.m_eventHandlers.gamepad_button or nil
	menu:registerEventHandler( "gamepad_button", function ( element, event )
		local source = nil
		local button = event.button
		if button == "shoulderl" or button == "left_shoulder" or button == Enum.LUIButton.LUI_KEY_LB then
			source = "LB"
		elseif button == "shoulderr" or button == "right_shoulder" or button == Enum.LUIButton.LUI_KEY_RB then
			source = "RB"
		elseif button == "key_shortcut" and type( event.key ) == "string" then
			local key = string.upper( event.key )
			if key == "Q" or key == "E" then
				source = key
			end
		end
		if source ~= nil then
			Z.TabHoldEdge( element, event.controller or controller, source, Z.TabHoldSources[source], "raw", event.down )
			return true
		end
		if previous ~= nil then
			return previous( element, event )
		end
	end )
end

-- Where the list was looking, and putting it back.
--
-- LUIGridLayout's setDataSource calls updateDataSource, which calls
-- clearLayout and puts the starting row back to 1. Restoring the selected row
-- afterwards makes it visible again, but anywhere in the window -- a row that
-- was fourth from the top comes back first -- so a rebuild halfway down a long
-- category reads as the page jumping.
--
-- The window therefore has to be moved back, and it has to be moved back
-- *without* asking for another datasource rebuild: updateDataSource is the
-- very path that cleared it, so calling that to apply a viewport throws the
-- viewport away again and builds the list twice. updateCurrentPosition and
-- updateLayout move the window on the list that is already built.
Z.CaptureView = function ( menu )
	local list = menu ~= nil and menu.Options or nil
	if list == nil then
		return nil
	end
	-- The row is remembered by name as well as by position: one appearing or
	-- going shifts every index below it, and going by index alone would put
	-- the cursor on a different setting.
	local active = list.activeWidget
	local index = active ~= nil and active.gridInfoTable ~= nil
		and active.gridInfoTable.zeroBasedIndex or list.savedActiveIndex or 0
	local row = ( menu.zpRows or {} )[index + 1]
	return {
		tabId = menu.zpTabId,
		index = index,
		rowKey = row ~= nil and tostring( row.dvar or "" ) or "",
		first = list.currentStartRow or 1,
		column = list.currentStartColumn or 1,
	}
end

Z.RestoreView = function ( menu, view )
	if view == nil or menu == nil or menu.Options == nil then
		return
	end
	-- Not onto a different category: the window of the one being left means
	-- nothing on the one arrived at.
	if view.tabId ~= nil and menu.zpTabId ~= view.tabId then
		return
	end
	local list = menu.Options
	local rows = menu.zpRows or {}
	if #rows == 0 then
		return
	end

	local index = math.min( view.index or 0, #rows - 1 )
	if view.rowKey ~= nil and view.rowKey ~= "" then
		for candidate, row in ipairs( rows ) do
			if tostring( row.dvar or "" ) == view.rowKey then
				index = candidate - 1
				break
			end
		end
	end
	index = math.max( 0, index )

	-- Clamped to a window that exists on the category as it now stands, and
	-- then to one the selected row is actually inside -- rows can have gone.
	local visible = math.max( 1, list.vCount or 1 )
	local first = math.max( 1, math.min( view.first or 1, math.max( 1, #rows - visible + 1 ) ) )
	first = math.min( first, index + 1 )
	first = math.max( first, index - visible + 2 )

	if type( list.updateCurrentPosition ) == "function" then
		list:updateCurrentPosition( first, view.column or list.currentStartColumn or 1 )
		list:updateLayout( 0 )
	end
	if type( list.setActiveIndex ) == "function" then
		list:setActiveIndex( index + 1, 1, 0, true )
	end
	if type( list.updateScrollbars ) == "function" then
		list:updateScrollbars()
	end
end

-- A tab with nothing in it. The details panel is linked to the list's
-- selected row, and an empty list selects nothing, so it would otherwise
-- keep the last row of the tab you just left.
Z.ShowEmpty = function ( menu )
	if menu.DetailsTitle ~= nil then
		menu.DetailsTitle:setText( Z.Text( "ui.no_settings", "NO SETTINGS" ) )
	end
	for _, element in ipairs( {
		menu.DetailsDvar,
		menu.DetailsDescription,
		menu.DetailsDefault,
		menu.DetailsBoundary,
		menu.DetailsScope
	} ) do
		if element ~= nil then
			element:setText( "" )
		end
	end
end

-- Moving to a tab keeps where the cursor was on the one being left, so
-- stepping across the tabs and back does not lose your place.
Z.ShowTab = function ( menu, controller, id, force )
	if menu == nil or menu.Options == nil or id == nil then
		return
	end
	-- Moving to the category already on screen is nothing, unless the rows
	-- under it have just been rebuilt.
	if id == menu.zpTabId and force ~= true then
		return
	end
	local tab = Z.FindTab( menu.zpTabs, id )
	if tab == nil or not Z.TabEnabled( tab, controller ) then
		return
	end
	if menu.zpTabId ~= nil then
		menu.zpTabAt[menu.zpTabId] = menu.Options.savedActiveIndex or 0
	end
	-- A rebuild of the category already on screen keeps the player where
	-- they are standing: the snapshot carries the row's own name and the
	-- window it was in, and both go back after the list is built.
	local heldView = nil
	if force == true and id == menu.zpTabId then
		heldView = Z.CaptureView( menu )
	end
	menu.zpTabId = id
	menu.zpTab = tab
	menu.zpChangedOnly = false
	menu.zpSource = menu.zpSources[id]
	menu.zpRows = Z.TabRows( tab )
	-- Rebuilt rather than reused: a tab whose rows are a function -- a
	-- report, or another mod's changed list -- answers differently each
	-- time it is asked.
	Z.BuildRows( menu.zpSource, menu.zpRows, tab, controller )
	if menu.Title ~= nil then
		menu.Title:setText( Z.TabTitle( tab, menu.zpTabs ) )
	end
	menu.Subtitle:setText( Z.TabHint( tab ) )
	menu.Options.savedActiveIndex = menu.zpTabAt[id] or 0
	menu.Options:setDataSource( menu.zpSource )
	Z.RestoreView( menu, heldView )
	Z.SyncScrollbar( menu )
	Z.UpdateTabNavigation( menu, id, controller )
	if #menu.zpRows == 0 then
		Z.ShowEmpty( menu )
	end
end

-- The rows as they now stand, after something has changed several at once.
Z.Rebuild = function ( menu, controller )
	if menu == nil or menu.Options == nil then
		return
	end
	local view = Z.CaptureView( menu )
	menu.zpRows = Z.TabRows( menu.zpTab )
	Z.BuildRows( menu.zpSource, menu.zpRows, menu.zpTab, controller )
	menu.Options:setDataSource( menu.zpSource )
	Z.RestoreView( menu, view )
	Z.SyncScrollbar( menu )
	menu.Options:processEvent( {
		name = "gain_focus",
		controller = controller
	} )
end

-- ------------------------------------------------------------------------
-- Reset and randomize
-- ------------------------------------------------------------------------

-- Every registered tab's own save, ours included. Called once when the page
-- closes and again after a bulk action, so a crash between the two leaves the
-- change on disk rather than only in the dvars.
Z.FlushTabs = function ( controller )
	Z.Flush( controller )
	for _, tab in ipairs( B.GetTabs( controller ) ) do
		if type( tab.flush ) == "function" then
			pcall( tab.flush, controller, tab )
		end
	end
end

-- Every ZPause setting, back to its default, for a page that is ZPause's
-- alone. The shared transaction above is what a bundle uses; this is the
-- short way round when there is nobody else on the screen.
Z.ResetAll = function ( controller, menu )
	Z.ClearPicked()
	for _, row in ipairs( Z.AllRows ) do
		Z.TabSet( controller, row.dvar, row.default, row )
	end
	Z.Flush( controller )
	Z.QueueRefreshTabs( menu, controller, menu ~= nil and menu.zpTabId or nil )
end

-- One reset, however many categories and mods it covers. Every row is written
-- through the owner's own set -- nobody else's storage is touched by hand --
-- each owner is flushed once at the end rather than after every row, and the
-- page is rebuilt once, after all of it, by whoever asked.
--
-- A row is written even where the value it already holds looks right: what
-- the shell can see is the dvar, and the component's own record is its own
-- business.
Z.ResetRows = function ( controller, tabs )
	Z.ClearPicked()
	local flushed = {}
	local done = {}
	local wholeOwner = {}

	-- Whether an owner's whole-owner reset may run is a question about the
	-- owner, not about one of its categories: that reset puts back every
	-- page the owner has, not the one being looked at. So the state is
	-- gathered across everything in this reset before any of it is decided.
	-- A row this shell can write, a setter of its own, or a single row the
	-- player may not write all mean something narrower than the owner-wide
	-- reset is in scope.
	--
	-- Not writable covers more than unavailable does: a row declared read
	-- only is rejected by Writable alone, which is how one of those used to
	-- let the owner-wide reset through.
	local owner = {}
	for _, tab in ipairs( tabs or {} ) do
		local id = tostring( tab.owner )
		owner[id] = owner[id] or { writable = false, blocked = false, setter = false, reset = false }
		if type( tab.set ) == "function" then
			owner[id].setter = true
		end
		if type( tab.reset ) == "function" then
			owner[id].reset = true
		end
		for _, row in ipairs( Z.TabRows( tab ) ) do
			if Z.Writable( row, tab, controller ) then
				owner[id].writable = true
			else
				owner[id].blocked = true
			end
		end
	end

	for _, tab in ipairs( tabs or {} ) do
		for _, row in ipairs( Z.TabRows( tab ) ) do
			if Z.Writable( row, tab, controller ) then
				local key = tostring( tab.owner ) .. "\0" .. tostring( row.dvar )
				if not done[key] then
					done[key] = true
					Z.Apply( controller, tab, row, row.default )
				end
			end
		end
	end

	-- A component built against an older contract, with nothing this shell
	-- can write: its own reset is the way in, asked once for the whole
	-- owner. A host's action, since the values behind it are the host's.
	local isHost = B.HostStatus == nil or B.HostStatus( controller ) == "HOST"
	for _, tab in ipairs( tabs or {} ) do
		local id = tostring( tab.owner )
		local state = owner[id]
		if isHost and state ~= nil and state.reset and not state.writable
			and not state.blocked and not state.setter
			and type( tab.reset ) == "function" and not wholeOwner[id] then
			-- Its own table, not the flush one: an owner whose reset ran
			-- still wants flushing, and sharing a marker between the two
			-- would quietly skip it.
			wholeOwner[id] = true
			pcall( tab.reset, controller, nil, tab )
		end
	end
	for _, tab in ipairs( tabs or {} ) do
		if not flushed[tab.owner] and type( tab.flush ) == "function" then
			flushed[tab.owner] = true
			pcall( tab.flush, controller, tab )
		end
	end
end

-- RESET ALL is every editable category on the screen, which in a bundle is
-- every mod's. One button, one meaning, wherever it is pressed from.
Z.ResetOwner = function ( controller, menu )
	local editable = {}
	for _, tab in ipairs( B.GetTabs( controller ) ) do
		if tab.role ~= "changed" and tab.role ~= "mods" and tab.role ~= "report" then
			table.insert( editable, tab )
		end
	end
	Z.ResetRows( controller, editable )
	Z.QueueRefreshTabs( menu, controller, menu ~= nil and menu.zpTabId or nil )
end

Z.ResetTab = function ( controller, menu )
	local tab = menu ~= nil and menu.zpTab or nil
	if tab == nil then
		return
	end
	Z.ResetRows( controller, { tab } )
	Z.QueueRefreshTabs( menu, controller, menu.zpTabId )
end

Z.RandomizeTab = function ( controller, menu )
	Z.ClearPicked()
	local tab = menu ~= nil and menu.zpTab or nil
	if tab == nil then
		return
	end
	for _, row in ipairs( Z.TabRows( tab ) ) do
		if Z.Writable( row, tab, controller ) then
			-- DEFAULT is one of the choices. A randomize that could only
			-- ever pick a value would leave a page there was no way back
			-- from except resetting it by hand.
			local choices = {
				row.default
			}
			for _, value in ipairs( row.values or {} ) do
				if not Z.Same( value, row.default ) then
					table.insert( choices, value )
				end
			end
			Z.Apply( controller, tab, row, choices[math.random( #choices )] )
		end
	end
	if type( tab.flush ) == "function" then
		pcall( tab.flush, controller, tab )
	end
	Z.QueueRefreshTabs( menu, controller, menu.zpTabId )
end

-- Asked first, the way the game asks before anything it cannot take back,
-- with NO under the cursor. One builder for all three: the only differences
-- are what it says and what YES does.
Z.Ask = function ( controller, settings, name, title, description, confirmed )
	CoD.OverlayUtility.AddSystemOverlay( name, {
		menuName = "SystemOverlay_Compact",
		title = title,
		description = description,
		categoryType = CoD.OverlayUtility.OverlayTypes.Alert,
		listDatasource = function ()
			DataSources[name .. "_List"] = DataSourceHelpers.ListSetup( name .. "_List", function ()
				return {
					{
						models = {
							displayText = Engine.Localize( "MENU_NO" )
						},
						properties = {
							action = function ( self, element, choiceController, param, menu )
								GoBack( menu, choiceController )
							end
						}
					},
					{
						models = {
							displayText = Engine.Localize( "MENU_YES" )
						},
						properties = {
							action = function ( self, element, choiceController, param, menu )
								-- The overlay starts closing first. A rebuild
								-- asked for while it still occludes the page
								-- lands on recycled rows and leaves the page
								-- showing what it showed before the reset
								-- until the category is changed.
								GoBack( menu, choiceController )
								confirmed( choiceController, settings )
							end
						}
					}
				}
			end, true, nil )
			return name .. "_List"
		end
	} )
	CoD.OverlayUtility.CreateOverlay( controller, settings, name )
end

Z.AskResetTab = function ( controller, settings )
	Z.Ask( controller, settings, "ZPauseSettingsResetTab",
		Z.Text( "ui.reset_tab", "RESET TAB" ),
		Z.Text( "ui.reset_tab_ask", "Put every setting on this tab back to its default?" ),
		Z.ResetTab )
end

Z.AskRandomize = function ( controller, settings )
	Z.Ask( controller, settings, "ZPauseSettingsRandomize",
		Z.Text( "ui.randomize", "RANDOMIZE" ),
		Z.Text( "ui.randomize_ask",
			"Choose a random value for every setting on this tab? DEFAULT is one of them." ),
		Z.RandomizeTab )
end

Z.AskReset = function ( controller, settings )
	local ask = Z.Text( "ui.reset_ask", "Put every ZPause setting back to its default?" )
	if B.IsBundle() then
		ask = Z.Text( "ui.reset_all_ask",
			"Put every setting on this screen back to its default, for every mod on it?" )
	end
	Z.Ask( controller, settings, "ZPauseSettingsReset",
		Z.Text( "ui.reset", "RESET TO DEFAULTS" ), ask, Z.ResetOwner )
end

Z.Back = function ( menu, controller )
	Z.FlushTabs( controller )
	GoBack( menu, controller )
	ClearSavedState( menu, controller )
end

-- ------------------------------------------------------------------------
-- The one builder, for both ways in
-- ------------------------------------------------------------------------

Z.CreateMenu = function ( controller, menuName )
	Z.ClearPicked()
	require( "ui.uieditor.widgets.StartMenu.StartMenu_Options_Slider_Small" )
	require( "ui.uieditor.widgets.StartMenu.StartMenu_Options_Slider_Control_Item_Small" )
	require( "ui.uieditor.widgets.Lobby.Common.List1ButtonLarge_PH" )
	require( "ui.uieditor.widgets.TabbedWidgets.basicTabList" )
	require( "ui.uieditor.widgets.TabbedWidgets.paintshopTabWidget" )
	require( "ui.uieditor.widgets.BumperButtonWithKeyMouse" )
	require( "ui.uieditor.widgets.Scrollbars.verticalScrollbar" )

	-- The stock slider makes its arrows clickable but leaves the value text
	-- inert, and the text is the part a mouse goes for. TextBox belongs to
	-- the inner control item rather than to the slider, so the click target
	-- goes there; loopEdges on the rows brings the last value round to
	-- DEFAULT again.
	-- Everything ZPause does to one of these controls, kept apart from
	-- creating the class, because the class may not be ours to create.
	Z.DecorateControlItem = Z.DecorateControlItem or function ( widget, owner, ownerController )
		if widget == nil or widget.zpDecorated == true then
			return widget
		end
		widget.zpDecorated = true
		-- An inert row keeps one value and no arrows. Hiding them once
		-- is not enough: the stock control's own Focus and Default
		-- clips write arrow alpha back every time the row is hovered or
		-- focused, and the visible icon is arrow.arrow, whose Over clip
		-- writes its own alpha independently of its parent's. So the
		-- setter is wrapped on both, and the state the clips ask for is
		-- replaced while the row is locked.
		for _, arrow in ipairs( { widget.left, widget.right } ) do
			if arrow ~= nil then
				for _, part in ipairs( { arrow, arrow.arrow } ) do
					if part ~= nil and type( part.setAlpha ) == "function" then
						local inheritedAlpha = part.setAlpha
						part.setAlpha = function ( element, alpha, ... )
							return inheritedAlpha( element,
								widget.zpOptionLocked and 0 or alpha, ... )
						end
					end
				end
			end
		end
		local inheritedState = widget.setState
		if type( inheritedState ) == "function" then
			widget.setState = function ( element, state, ... )
				if element.zpOptionLocked then
					state = "ArrowsHidden"
				end
				return inheritedState( element, state, ... )
			end
		end
		local applyLock = function ( locked )
			if widget.zpOptionLocked == locked then
				return
			end
			widget.zpOptionLocked = locked
			widget:setState( locked and "ArrowsHidden" or "DefaultState" )
			for _, arrow in ipairs( { widget.left, widget.right } ) do
				if arrow ~= nil then
					arrow:setAlpha( locked and 0 or 1 )
					if arrow.arrow ~= nil then
						arrow.arrow:setAlpha( locked and 0 or 1 )
					end
					arrow:setHandleMouse( not locked )
				end
			end
		end
		local reads = function ( value )
			return value == true or value == 1 or value == "1" or value == "true"
		end
		widget:linkToElementModel( widget, "zbOptionLocked", true, function ( model )
			applyLock( reads( Engine.GetModelValue( model ) ) )
		end )
		-- A recycled control can be handed an ordinary option carrying
		-- no lock model at all, and would keep the last row's arrows
		-- hidden. Its text always changes, so that is where the lock is
		-- settled again -- from the model where there is one, and from
		-- what the row says about itself where there is not.
		widget:linkToElementModel( widget, "text", true, function ( textModel )
			local model = widget:getModel( ownerController, "zbOptionLocked" )
			local value = model ~= nil and Engine.GetModelValue( model ) or nil
			local text = tostring( Engine.GetModelValue( textModel ) or "" )
			applyLock( reads( value )
				or string.find( text, "^DISABLED: " ) ~= nil
				or string.find( text, "^LOCKED: " ) ~= nil
				or string.find( text, "^HOST VALUE" ) ~= nil
				or string.find( text, "^HOST STATUS" ) ~= nil
				or Z.StatePrefixed( text ) )
		end )
		widget:setLeftRight( true, false, 0, 215 )
		widget.TextBox:setHandleMouse( true )
		widget.TextBox:registerEventHandler( "button_action", function ()
			-- An action row is pressed rather than cycled, so it is
			-- asked first; anything else takes the ordinary next value.
			if Z.ButtonRowAt( owner, ownerController, widget ) then
				return true
			end
			SendButtonPressToMenuEx( owner, ownerController, Enum.LUIButton.LUI_KEY_RIGHT )
			return true
		end )
		return widget
	end

	-- Another Z mod can reach this class first -- ZStats makes it so its own
	-- action rows answer to a click -- and a bundle is exactly where that
	-- happens. So the class is created only when it is missing, and the
	-- decoration goes on either way, wrapped around whatever constructor is
	-- already there. Marked on the class so opening the page a second time
	-- does not wrap it twice.
	if CoD.ZPause_Options_Slider_Control_Item_Small == nil then
		CoD.ZPause_Options_Slider_Control_Item_Small = InheritFrom( CoD.StartMenu_Options_Slider_Control_Item_Small )
		CoD.ZPause_Options_Slider_Control_Item_Small.new = function ( owner, ownerController )
			local widget = CoD.StartMenu_Options_Slider_Control_Item_Small.new( owner, ownerController )
			widget:setClass( CoD.ZPause_Options_Slider_Control_Item_Small )
			return widget
		end
	end
	local zpControl = CoD.ZPause_Options_Slider_Control_Item_Small
	if zpControl.zpDecorator ~= true and type( zpControl.new ) == "function" then
		local inheritedNew = zpControl.new
		zpControl.new = function ( owner, ownerController )
			return Z.DecorateControlItem( inheritedNew( owner, ownerController ), owner, ownerController )
		end
		zpControl.zpDecorator = true
	end
	-- The same split as the control above, for the same reason: whoever
	-- creates this class, ZPause's own geometry and row styling go on it.
	Z.DecorateRowWidget = Z.DecorateRowWidget or function ( widget, owner, ownerController )
		if widget == nil or widget.zpDecorated == true then
			return widget
		end
		widget.zpDecorated = true
		-- The last 20 of the list's 520 units are its scrollbar. What
		-- is left is halved between the name and its value, and the
		-- value control is widened so its arrows reach both edges.
		widget:setLeftRight( true, false, 0, 500 )
		widget.StartMenuframenoBG0:setLeftRight( true, true, 0, -254 )
		widget.StartMenuframenoBG1:setLeftRight( true, true, 254, -1 )
		widget.Title:setLeftRight( true, false, 20, 230 )
		widget.Slider:setLeftRight( true, false, 270, 485 )
		widget.altText:setLeftRight( true, false, 254, 499 )
		widget.FocusBarB:setLeftRight( true, true, 254, -2 )
		widget.FocusBarT:setLeftRight( true, true, 254, -2 )
		widget.Slider:setWidgetType( CoD.ZPause_Options_Slider_Control_Item_Small )

		-- Greyed where it is switched off, amber where its owner is
		-- holding it to a value, ordinary otherwise. Applied again
		-- after every setState, because the stock clips set the row's
		-- own alpha as it gains and loses focus.
		local applyRowState = function ()
			local state = widget.zpRowState
			widget:setAlpha( state == "DISABLED" and 0.52
				or ( state == "OVERRIDDEN" and 0.72 or 1 ) )
			if widget.Title ~= nil then
				if state == "DISABLED" then
					widget.Title:setRGB( 0.68, 0.68, 0.68 )
				elseif state == "OVERRIDDEN" then
					widget.Title:setRGB( 1, 0.7, 0.4 )
				else
					widget.Title:setRGB( 1, 1, 1 )
				end
			end
		end
		widget:linkToElementModel( widget, "zbRowState", true, function ( model )
			widget.zpRowState = Engine.GetModelValue( model )
			applyRowState()
		end )
		LUI.OverrideFunction_CallOriginalSecond( widget, "setState", applyRowState )

		-- A row on CHANGED carries its owner's name in front of the
		-- setting's and can outrun the name column. The text takes its
		-- size from the height of the element it is in, so a long one
		-- is given a shorter element -- and the row itself is left
		-- alone, since rows of different heights break the fixed
		-- viewport, the scrollbar's arithmetic and widget recycling.
		-- Written as a subscription rather than once, because that is
		-- also what puts the stock size back when a recycled widget is
		-- handed a shorter name.
		widget.Title:linkToElementModel( widget, "name", true, function ( model )
			local value = Engine.GetModelValue( model )
			local name = value ~= nil and Engine.Localize( value ) or ""
			local half = #name > 27 and 8.5 or 11
			widget.Title:setTopBottom( false, false, -half, half )
		end )

