	Z.InstallHeldShortcutBitGuard()
	Z.AttachTabHold( self, controller )

	-- Enter, or A on a pad, presses the action row under the cursor. On both
	-- pages: this renderer draws the whole bundle's categories and another
	-- mod's action row is reached the same way from the lobby as from the
	-- game's own pause menu. The prompt appears only while an action row is
	-- actually under the cursor, since on every other row the key does
	-- nothing. A callback that returns true ends the dispatch, so a mod that
	-- binds its own is not a second activation.
	self:AddButtonCallbackFunction( self, controller, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "ENTER",
		function ()
			return Z.ButtonRowAt( self, controller )
		end,
		function ( element, owner )
			CoD.Menu.SetButtonLabel( owner, Enum.LUIButton.LUI_KEY_XBA_PSCROSS, "MENU_SELECT" )
			return true
		end, false )

	self:processEvent( {
		name = "menu_loaded",
		controller = controller
	} )
	self:processEvent( {
		name = "update_state",
		menu = self
	} )
	Z.SyncScrollbar( self )
	if #self.zpRows == 0 then
		Z.ShowEmpty( self )
	end
	if not self:restoreState() then
		Options:processEvent( {
			name = "gain_focus",
			controller = controller
		} )
	end
	LUI.OverrideFunction_CallOriginalSecond( self, "close", function ( element )
		Z.StopTabHold( element )
		Z.FlushTabs( controller )
		element.Options:close()
		element.Back:close()
		element.Reset:close()
		element.Randomize:close()
		element.ResetAll:close()
		element.DetailsScope:close()
		element.ScopeLabel:close()
		element.DetailsBoundary:close()
		element.AppliesLabel:close()
		element.DetailsDefault:close()
		element.DefaultLabel:close()
		element.DetailsDescription:close()
		element.DescriptionLabel:close()
		element.DetailsDvar:close()
		element.DetailsTitle:close()
		element.DetailsAccent:close()
		element.Details:close()
		element.TabNext:close()
		element.TabPosition:close()
		element.TabPrevious:close()
		element.TabRight:close()
		element.Tabs:close()
		element.TabLeft:close()
		element.Subtitle:close()
			element.ComponentVersions:close()
			if element.HostStatus ~= nil then element.HostStatus:close() end
		element.Title:close()
		if element.Shade ~= nil then
			element.Shade:close()
		end
		element.Background:close()
		Engine.UnsubscribeAndFreeModel( Engine.GetModel( Engine.GetModelForController( controller ), menuName .. ".buttonPrompts" ) )
	end )
	if B.HostStatus ~= nil then
		local pollHost
		pollHost = function ()
			local status = B.HostStatus( controller )
			if status ~= self.zpHostState then
				self.zpHostState = status
				self.HostStatus:setText( Z.Shell( status ) )
				Z.QueueRefreshTabs( self, controller, self.zpTabId )
			end
			local ok, timer = pcall( LUI.UITimer.newElementTimer, 250, true, pollHost )
			if ok and timer ~= nil then self:addElement( timer ) end
		end
		pollHost()
	end
	return self
end


-- ------------------------------------------------------------------------
-- Losing the menu entry
--
-- The bundle-entry contract: in a bundle one owner's factory wins the screen,
-- and it is NOT whichever loaded first. The shell has two claim mechanisms -
-- created-when-absent goes to the first loader, a versioned upgrade goes to
-- the highest version whatever the order - and the shared menu kit installs
-- as the second. So the winner publishes B.MenuEntry and every other owner
-- asks for it here.
--
-- ZPause publishes no kit version of its own: it has no kit yet and must not
-- claim one it cannot honour. This is only the asking half, and it has to
-- exist before anybody wins, because a mod taught to win before the others
-- are taught to lose is two runtimes on one screen.
--
-- Standing down happens by never standing up. Every timer, hold-repeat and
-- button callback in this file is attached inside a menu, so returning here -
-- before anything is built - means none of it is ever attached. That is
-- better than unregistering, which would be a list to keep in step with
-- every future timer.
--
-- Absent or not a function means ZPause builds its own screen, as today. A
-- dead button when a claim went half-made is worse than the status quo.
Z.MenuEntryElsewhere = function ( mine )
	local entry = B ~= nil and B.MenuEntry or nil
	if type( entry ) ~= "function" then
		return nil
	end
	-- A caller that does not say who it is does not get to delegate. Without
	-- `mine` there is no way to tell our own handle from somebody else's, and
	-- delegating blindly is the recursion this guard exists for. Refusing
	-- means a forgetful call site draws ZPause's own screen, which is the
	-- same fail-open as every other branch here.
	--
	-- ZShare defaults `mine` to its own recorded handle instead, which fits a
	-- single entry chokepoint. There are three here, each with its own
	-- factory, so there is no one handle to default to and refusing is the
	-- half of that decision this shape can take.
	if type( mine ) ~= "function" then
		return nil
	end
	if entry == mine then
		return nil
	end
	return entry
end

LUI.createMenu.ZPauseSettings = function ( controller )
	local elsewhere = Z.MenuEntryElsewhere( LUI.createMenu.ZPauseSettings )
	if elsewhere ~= nil then
		return elsewhere( controller )
	end
	return Z.CreateMenu( controller, "ZPauseSettings" )
end

-- The second way in, and the pause-menu entry that opens it. Asked for here,
-- after everything above exists, because that file builds on it.
require( "zpauseingamesettings" )

-- ------------------------------------------------------------------------

-- The lobby button and the save file belong to the frontend. The page itself
-- does not, and is built above whatever this is: core_mod loads in every
-- mode, and T7x can keep a module across the step into a match, so a menu
-- defined only in the frontend would be one the pause menu could not open.
if Engine.GetCurrentMap() == "core_frontend" then
	Z.Hook()
	if LUI.roots ~= nil and LUI.roots.UIRootFull ~= nil then
		Z.Wait( LUI.roots.UIRootFull, 0 )
	end
end

-- And the one that runs wherever this file was read, frontend or match. Not
-- disposable, so it resets itself rather than leaving a new element behind on
-- every pass; it costs a table lookup once everything is read and written.
if LUI.roots ~= nil and LUI.roots.UIRootFull ~= nil and not CoD.ZPauseStorageKeeping then
	CoD.ZPauseStorageKeeping = true
	LUI.roots.UIRootFull:addElement( LUI.UITimer.newElementTimer( 5000, false, function ()
		Z.Keeper()
	end ) )
end

-- The row builder a bundle's finalizer recognises as this native generation.
Z.BundlePresentationNativeRow = Z.Row
